NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: 'MASAN kotier ni tapi o, a masan kotier ren Kot, a masan me udan Kot.',
        2: 'I me kotikot ren Kot ni tapi o.',
        3: 'I me dipisou karos tapi kidar, o sota man meakot mia, me kaidin i kotin wiadar.',
        4: 'Maur mi re a; o iei maur o marain en aramas.',
        5: 'A marain o me dakarada rotorot, a rotorot sota lingan kila.',
        6: 'Aramas amen me pakadarador sang ren Kot ad a Ioanes!',
        7: 'I me pwara dong kadede, pwen kadede marain o pwe karos en poson pweki i.',
        8: 'Kaidin i me marain o, a a kin kadede marain o.',
        9: 'Iei marain melel, me pwara dong sappa, ap kamaraini aramas karos.',
        10: 'I me kotier sappa, o i me sappa tapi kidar, a sappa sasa i.',
        11: 'A koti dong udan sapwilim a, a sapwilim a kan me san i.',
        12: 'Karos, me kasamo i, a kotiki ong ir manaman, en wiala seri en Kot, ir, me poson mar a,',
        13: 'Me kaidin ipwidi sang nta, de inong en uduk, de inong en ol o, pwe ipwidier sang ren Kot.',
        14: 'Masan me wia uduk ala o kotikot re atail, o kitail kilanger a lingan, lingan dueta lingan en Ieros eu sang ren Sam o, me dir en mak melel.',
        15: 'Ioanes me kadede i ngil laudeda indada: Iei i, me i padaki wei: Me pan kotido mur i, iei me mier mo i, pwe a kotikotier mo i.',
        16: 'Pwe kitail karos ale sang nan audepa a mak sapan potopot.',
        17: 'Pwe kapung me kokido sang Moses, a mak o melel sang Iesus Kristus.',
        18: 'Sota me kilanger Kot kokodo, Ol ieros ta, me kin kotikot pan kupur en Sam o, i me kotin kasaledar i.',
        19: 'A met en Ioanes a kadede, ni men Sus kadarala sang Ierusalem samero o lepit oko, pwen idok re a: Is koe?',
        20: 'I ari kotin kadede; a sota likam; a kotin kadede: Kaidin Kristus ngai.',
        21: 'Irail idok re a: A is? Elias komui? A masani: Kaidin ngai i. Komui saukop o? A sapeng: Kaidin.',
        22: 'Irail ap indang i: A is komui? Pwe sen sapeng irail me kadar kit dor. Da me komui kadedeki pein komui?',
        23: 'A masani: Ngai ngil eu, me likelikwir sili nan sap tan: Kaineneda al en Kaun o, duen saukop Iesaia masanier!',
        24: 'A irail pakadaradoer sang ren Parisär akan.',
        25: 'Irail ap idok re a indada: Da me komui wia paptaisiki, ma komui kaidin Kristus, o kaidin Elias, o pil kaidin saukop o?',
        26: 'Ioanes sapeng irail masani: Ngai me paptaisiki pil, a amen kin kotikot nan pung omail, me komail sasa.',
        27: 'Iei i me kotido mur i, me ngai sowar ong, en lapwada sal en sapwilim a sut.',
        28: 'Mepukat wiauier Petapara palilan Iordan, wasa Ioanes kin wia paptais ia.',
        29: 'Mandan ran o a masani Iesus a koti dong i ap masani: Kilang Sippul en Kot, me kin wawei dip en sappa!',
        30: 'Iei i, me i padaki wei: Ol amen pan kotido mur i iei, me mier mo i, pwe a kotikotier mo i.',
        31: 'A ngai so asa i, a pwe i en sansal dong Israel, iei me i kokido paptaisiki pil.',
        32: 'A Ioanes kadede masani: I kilanger Ngen o kotidido sang nanlang ni mom en muroi kotikot re a.',
        33: 'A ngai so asa i, a me porone ia don wia paptaisiki pil, iei me kotin masani ong ia: Me koe pan kilang. Ngen piridi sok poa, o kotikoteta re a, iei i, me kin wia paptaisiki Ngen saraui.',
        34: 'A i kilangadar ap kadedeki, me iei Sapwilim en Kot.',
        35: 'Mandan ran o Ioanes pil kotida wasa o, o na tounpadak riamen iang i.',
        36: 'A ni a udial Iesus kotikot kokodo, ap masani: Kilang Sippul en Kot!',
        37: 'A tounpadak riamen rongadar a masan, ap idauen wei Iesus.',
        38: 'Iesus ap kotin saupeido masani ara idedauen, ap kotin masani ong ira: Da me koma rapaki? Ira potoan ong: Rapi (iet wewe: Saunpadak), ia wasa re kin kotikot ia?',
        39: 'A kotin masani ong ira: Kodo kilang! Ira ap poto dong kilanger wasa, me a kotikot ia, ap mimieta re a ni ran o. Mepukat wiauier impan auer kaeisok.',
        40: 'Andreas, ri en Simon Petrus amen re ra, me rongadar sang ren Ioanes ap idedauen i.',
        41: 'I me diaradar mas udan ri a Simon, indai ong i: Se diaradar Mesias (iet wewe: Kristus).',
        42: 'I ap kalualang i ren Iesus. A Iesus lao masani i, ap masani: Simon, koe nain Iona, koe nok adaneki Kepas (iet wewe: Paip).',
        43: 'Mandan ran o a pan kotilang Kaliläa, Iesus ap kotin diaradar Pilipus, masani ong i: Idauen ia do!',
        44: 'Pilipus men Petsaida, kanim en Andreas o Petrus.',
        45: 'Pilipus diaradar Natanael, ap indang i: Se diaradar i, duen me Moses intingiedier nan puk en kapung o saukop akan: Iesus men Nasaret, sapwilim en Iosep.',
        46: 'A Natanael indai ong i: Pala maukot pan kak pwarada sang Nasaret? Pilipus indang i: Kodo kilang!',
        47: 'Iesus kotin masani Natanael koko dong i, ap masani duen i: Kilang, ol melel en Israel amen, me sota kin widing.',
        48: 'Natanael potoan ong i: Re kotin mangi ia sang ia? Iesus kotin sapeng masani ong i: Mon Pilipus a eker uk edo, ni om mod pan tuka pik o, I kilang uk ada.',
        49: 'Natanael sapeng potoan ong i: Rapi, ir me Sapwilim en Kot, ir me Nanmarki en Israel.',
        50: 'Iesus kotin sapeng masani ong i: Pweki I indai ong uk, me I kilang uk ada pan tuka pik o, iei me koe posonki, a koe nok kilang me lapa sang mepukat.',
        51: 'A kotin masani ong i: Melel, melel I indai ong komail, sang met komail pan kilang nanlang a ritida o tounlang en Kot akan dauda o daudi pwarado ren Nain aramas.',
    },
    2: {
        1: 'A NI kasilu en ran kamadip en kapapaud wiaui Kana nan Kaliläa; a in en Iesus kot wasa o.',
        2: 'Iesus o sapwilim a tounpadak kan me pil luke dong kamadip o.',
        3: 'Arail wain lao roselar, in en Iesus ap masani ong i: Solar arail wain.',
        4: 'Iesus kotin masani ong i: Li, menda re om? Ai ansau saikenta leler.',
        5: 'In a ap masani ong papa kan: Komail wiada meakaros, me a pan kotin masani ong komail.',
        6: 'Ari, potel takai wonu mi wasa o, en Sus akan ar men dopedop lole. Eu me laude ong metreten riau de silu.',
        7: 'Iesus kotin masani ong irail: Komail idip ong pil en potel akan! Irail ari kodiada lel au ar.',
        8: 'A ap kotin masani ong irail: Deukada, wala ren me kaun en konot: Irail ap wala.',
        9: 'Kaun en konot lao song kis pil, me wia wain la, o so asa, a idipi sang ia, a papa kan, me idip pil da, asa. Kaun en konot ap ekeredo ol kamod o,',
        10: 'Indang i: Aramas karos kin kida mas wain mau, toun kamadip lao medilar, re kin kida, me sota non mau. A komui kin nekinekid wain mau lel met.',
        11: 'I met tapidan kilel akan, me Iesus kotin wiadar Kana nan Kaliläa, o kotin kasaleda a lingan, o sapwilim a tounpadak kan posonla i.',
        12: 'A murin met a kotidilang Kapernaum, i o in a, o ri a ol akan, o sapwilim a tounpadak kan, ari, sota non ran toto, me re kotikot wasa o.',
        13: 'A pasa en Sus akan me korendor, a Iesus kotidalang Ierusalem.',
        14: 'A kotin masani nan im en kaudok men netinet en kau, o sip, o muroi, o men wiliandi moni me momod ia.',
        15: 'Ap kotin wiakida men wokiwok sal akai, ap woki ir sang nan im en kaudok iangaki sip o kau akan, o moni en saunwiliandi a kotin kasapokela o kotin wukedidi tepel akan.',
        16: 'Ap kotin masani ong men netinet en muroi kan: Wawei sang met met akan, o der wiakidar tanpas en Sam ai im en net eu!',
        17: 'A sapwilim a tounpadak kan tamanda me intingidier: Limpok ong tanpas omui me kasor ia dier.',
        18: 'Sus oko ap sapeng indang i: Kilel da, me kom kadedeki ong kit, me komui manaman ong, en wiada mepukat?',
        19: 'Iesus kotin sapeng masani ong irail: Palanga pasang im en kaudok wet, a pong sili pong I pan kauada.',
        20: 'Sus oko ap indada: Par ngaulwonu me im en kaudok wet wiaui kidar, a pong sili pong komui pan kaua kida?',
        21: 'Ari, tanpas en pali war a, me a kotin masanie kida.',
        22: 'A lao iasadar sang a matalar, sapwilim a tounpadak kan ap tamandar, me a kotin masanier mepukat. Irail ari poson kisin likau kan o masan, me Iesus kotin masaniadar.',
        23: 'Ni a kotikot Ierusalem ni pasa, ni kamadip o, me toto posonla mar a, ni ar kilanger kilel akan, me a kotin wiadar.',
        24: 'A Iesus sota kotin liki ong ir pein i, pwe a kotin mangi irail karos.',
        25: 'O a sota mau ong, meamen en kadede ong i aramas amen, pwe pein i kotin mangi lol en aramas.',
    },
    3: {
        1: 'ARAMAS amen mia, kisan Parsär akan, me mar a Nikodemus, me saumas amen ren Sus akan,',
        2: 'Me poto dong i ni pong o, katiti ong i: Rapi, se asa, me komui saunpadak amen, me tapido sang ren Kot, pwe sota, me kak wia kilel akan due me komui kotin wiada, ma Kot so iang.',
        3: 'Iesus kotin sapeng masani ong i: Melel, melel I indai ong uk, meamen so ipwi sapal, sota pan kak kilang wein Kot.',
        4: 'Nikodemus potoan ong i: Iaduen aramas laud pan kak ipwidi? A pan kak pur ong nan kaped en in a, ipwidi sang?',
        5: 'Iesus kotin sapeng: Melel, melel I indai ong uk, meamen so ipwiki pil o ngen, a sota kak pedelong ong nan wein Kot!',
        6: 'Me ipwiki uduk, iei uduk, a me ipwiki Ngen, iei ngen.',
        7: 'Koe der puriamuiki, me I katitiki ong uk: Komail en ipwi sapal.',
        8: 'Ang kin pein ipip sili, o koe kin rong ngil a, a koe sasa, wasa a tapi sang ia o wasa a ko ong ia; iduen amen amen, me ipwiki Ngen.',
        9: 'Nikodemus sapeng indai ong i: Iaduen mepukat kak wiaui?',
        10: 'Iesus kotin sapeng masani ong i: Saunpadak en Israel amen koe, a koe sasa duen mepukat?',
        11: 'Melel, melel I indai ong uk, me se asadar, iei me se kin indada, o me se kilanger, iei me se katitiki, a komail sota kin kamelele at kadede.',
        12: 'Ma I katitiki ong komail men pa, a komail ap sota kamelele, a iaduen, komail pan kamelele, ma I katitiki ong komail men nanlang?',
        13: 'Sota meamen, me kodala nanlang, i eta, me kodido sang nanlang, Nain aramas, me kin mimieta nanlang.',
        14: 'Duen Moses me kauadar serpent amen nan sap tan, iduen Nain aramas pan kakauda.',
        15: 'Pwe meamen posonla i, sota pan lokidokila, a en aneki maur soutuk.',
        16: 'Pwe iet duen Kot kotin kupura sappa, me a kotikidoki sapwilim a Ieros, pwe karos, me posonla i, ender salongala, a en aneki maur soutuk.',
        17: 'Pwe Kot me kotin porone dong sappa sapwilim a Ol, kaidin en kadeikada sappa, a pwe sappa en kamauri kila i.',
        18: 'Me poson i, sota pan pakadeikada, a me so poson i, iei pakadeikadar, pweki a sota poson mar en sapwilim en Kot ieros.',
        19: 'A iet kadeik o, marain pwara dong sappa, a aramas pok ong rotorot mon marain, pweki ar wiawia kan me sued.',
        20: 'Pwe amen amen, me wiawia sued, kin kailongki marain, o sota kin pwara dong marain, pwe a wiawia kan de sansaleda.',
        21: 'A me wiawia melel, kin ko dong marain, pwe a wiawia kan en sansaleda, me re tapi sang ren Kot.',
        22: 'Murin mepukat Iesus o sapwilim a tounpadak kan kotilang sap en Iudäa ap kotikot ia wia paptais.',
        23: 'A Ioanes pil wia paptais Enon koren iong Salim, aki pil toto mi wasa o, irail ari koieila paptaisela.',
        24: 'Pwe Ioanes saikenta lokidokilar nan imateng.',
        25: 'En Ioanes a tounpadak kan o ol en Sus amen ap akamaiki pena duen kamakelekel.',
        26: 'Irail ari ko dong ren Ioanes indang i: Rapi, me kot re omui palilan Iordan, me komui kin kadede, masani, a kin wia paptais o karos kin pwarala re a.',
        27: 'Ioanes sapeng masani: Aramas amen sota kak aneki meakot, ma a so aneki sang nanlang.',
        28: 'Komail pein kadede kin ia, me i indada: Kaidin Kristus ngai, pwe ngai me pakatarador mo a.',
        29: 'Me li amen kisin nin ong, iei ol kamod. A kompoke pan ol kamod kin u rongerong perenki ngil en ol kamod; ari, iei ai peren unsokala.',
        30: 'I en kakairida, a ngai en kakairidi.',
        31: 'Me kotido sang poa, i me poedi karos, a me kisan sappa, iei men sappa, o a kin kasokasoia duen sappa. A me kotido sang nanlang, me poedi karos,',
        32: 'O me a kilangada o rongada, iei me a kin kadedeki, a sota me kamelele a kadede.',
        33: 'A me kamelele a kadede, kin kadede, me Kot me melel.',
        34: 'Pwe i, me Kot kotin poronedor, kin kida en Kot a masan, pwe Kot sota kotikida Ngen ki men song.',
        35: 'Sam me kotin kupura sapwilim a Ol o kotiki onger ni lim a meakaros.',
        36: 'Me poson sapwilim a Ol, aneki maur soutuk. A me sota poson sapwilim a Ol, sota pan kilang maur, a ongiong en Kot pan mimieta re a.',
    },
    4: {
        1: 'KAUN lao kotin mangi, me Parisär akan rongadar, me Iesus kin wiada tounpadak kan o paptais toto sang Ioanes,',
        2: 'Ari, pwe sota me pein Iesus kotin paptais, sapwilim a tounpadak kan ta,',
        3: 'Ap kotila sang Iudäa, kotin purelang Kaliläa.',
        4: 'A a kotin weid nan wein Samaria.',
        5: 'I ap kotilang kanim en Samaria eu, me adaneki Sikar, koren iong sap, me Iakop ki ong na ol Iosep.',
        6: 'Iei wasa en Iakop a parer eu mia. Iesus ari ngirekila a sapasapal, ap kaipokedi pon parer o, ari mepukat wiauier impan auer kawonu.',
        7: 'A li en Samaria amen ap kodon idip pil ia. Iesus kotin masani ong i: Kido lim ai kis pil en!',
        8: 'Pwe sapwilim a tounpadak kan ko ong nan kanim, pan netiada sak arail.',
        9: 'Li en Samaria ap indang i: Iaduen, komui kisan men Sus, ap poeki pil re i? Pwe ngai li en Samaria amen, pwe Sus akan sota kin waroki ong men Samaria.',
        10: 'Iesus kotin sapeng masani ong i: Ma koe asa duen kisakis sang ren Kot o is i, me indang uk: Kido lim ai kis pil en, koe pan poeki re a, a ap pan ki ong uk pil memaur.',
        11: 'Li o indang i: Maing, sota sapwilim omui men idip pil, a parer me lol, a ia wasa, kom pan idip sang ia pil memaur?',
        12: 'De komui lapa sang sam at Iakop, me kotiki ong kit er parer en, o pein nima sang, o na kan, o na man akan?',
        13: 'Iesus kotin sapeng masani ong i: Karos, me nima sang pil wet, pan pur ong men nim pilada.',
        14: 'A meamen, me nima sang pil, me I ki ong i, pan solar men nim pilada kokolata, pwe pil, me I kin ki ong, pan pot loli kusukusudang maur soutuk.',
        15: 'Li o ap indai ong i: Maing, kom kotiki ong ia kisan pil o, pwe i en solar men nim pil, o solar kodo o idipa sang met!',
        16: 'Iesus kotin masani ong i: Kowei ukedo om paud!',
        17: 'Li o sapeng indada: Sota ai paud. Iesus kotin masani ong i: Melel om lokaia: Sota ai paud.',
        18: 'Pwe om paud me limen mas kokodo, a kaidik om paud, me koe paudeki met; iei melel, me koe indada.',
        19: 'Li o indang i: Maing, i ap asaer, me saukop amen komui.',
        20: 'Sam at akan kaukaudok pon nana wet, a komail kin inda dene Ierusalem eta wasa me aramas en kaudok ia.',
        21: 'Iesus kotin masani ong i: Li, kamelele ia, a korendor ansaun omail pan solar kaukaudok ong Sam pon nana wet, pil sota Ierusalem.',
        22: 'Komail kin sasa, me komail kin kaukaudok ong. A kit asa, me se kaukaudok ong, pwe kamaur pwarado sang ren men Sus akan.',
        23: 'A ansau korendor, ari a leler, me toun kaudok melel akan pan kaudok ong Sam ni Ngen o melel, pwe iei ta song en toun kaudok kan, me Sam pil kotin kupura.',
        24: 'Ngen eu Kot, a me kaudok ong i, ren kaudokki Ngen o melel.',
        25: 'Li indai ong i: I asa, me Mesias pan kotido, me maraneki Kristus. I lao kotido, a pan katiti ong kit meakaros.',
        26: 'Iesus kotin masani ong i: Ngai i, me lokelokaia ong uk.',
        27: 'A sapwilim a tounpadak kan ap purodo, puriamui a masan ong li amen. Ari so, sota me indada: Da me re kotin kainoma, de da me re kotin mamasani ong i?',
        28: 'Li o ap pwilikidi potel en pil o, ap koieilang kanim o kasoi ong aramas akan:',
        29: 'Kodo, kilang aramas amen, me kasale ong ia karos, me i wiadar, ma i kaidin Kristus?',
        30: 'Rap koieila sang nan kanim o potodo re a.',
        31: 'Ni ansau ota sapwilim a tounpadak kan poeki re a, potoan ong: Rapi, re kotin konot!',
        32: 'A kotin masani ong irail: Kan ai kisin manga mia, me komail sasa.',
        33: 'Tounpadak kan ap kasokasoi nan pung arail: Muein amen wa dong i sak.',
        34: 'Iesus kotin masani ong irail: Wiawia kupur en me kadar ia do, o kapwaiada sapwilim a dodok, iei kan ai,',
        35: 'Komail sota kin indada: Saunipong paieu mi mon rak? Kilan, I indai ong komail, sarada, kilang matuel o pwe a malar.',
        36: 'Me dolung kin pwaipwai o nanak ong maur soutuk, pwe ira karos, me kamorok o me dolung en peren pena.',
        37: 'Pwe ni mepukat kasoi o pwaidar: Amen me kin kamokamorok, a amen me kin dolung.',
        38: 'I kadar komail wei, en dolung pena, me komail so doke, Akai me dodoker, a komail me id aneki arail rak.',
        39: 'Men Samaria toto kisan kanim o posonla i pweki kasoi en li o, me kadede: A kotin kasale ong ia karos, me i wiadar.',
        40: 'Men Samaria kan lao pokon dong i, rap poeki re a, en kotikot re’rail. I ari kotikot ia pong ria pong.',
        41: 'A me toto me posonlar pweki a masan,',
        42: 'Ap indang li o: Se poson kila kaidin om kasoi, pwe se pein rongadar o weweki, me i melel Saunkamaur pan sappa.',
        43: 'Murin ran riau Iesus kotila sang wasa o, kotilang Kaliläa.',
        44: 'Pwe pein Iesus kotin kadedeki, me saukop amen sota kin mau nan udan sap we.',
        45: 'A lao kotilang Kaliläa, men Kaliläa me kasamo i, pwe re iang kilanger me a kotin wiadar Ierusalem ni kamadip o, pwe re toun iang kamadip.',
        46: 'Iesus ari kotin pure dong Kana nan Kaliläa, wasa a kotin kapikila pil wain. A monsap amen mia, me na ol somau nan Kapernaum.',
        47: 'A lao rongadar, me Iesus koti dong Kaliläa sang Iudäa, ap poto dong re a, poeki i en kotidi, kakelada na ol, pwe a koren iong mela.',
        48: 'Iesus ap kotin masani ong i: Ma komail so kilang kilel o manaman akan komail sota pan poson.',
        49: 'Monsap potoan ong i: Maing kotidi mon nai seri mela!',
        50: 'Iesus kotin masani ong i: U kowei, noum ol memaur. Ari aramas o poson masan o, me Iesus kotin masani ong i ap koieila.',
        51: 'A ni a kodila, a ladu kan me tu ong i, kasoi ong i, me na putak mauredar.',
        52: 'I ap kalelapok re’rail: Ansau da me a pikikidi maur? Irail indang i: Aio ni auer kaisu karakar ko sanger.',
        53: 'Sam o ap asadar, me i ansau, me Iesus kotin masani ong i: Noum ol memaur. I ari o na kan me posonla i.',
        54: 'Iet kilel kariau, me Iesus kotin wiadar ni a koti dong Kaliläa sang Iudäa.',
    },
    5: {
        1: 'MURIN mepukat ran lapalap eu en Sus oko pwaida; Iesus ap kotilang Ierusalem.',
        2: 'Len pil eu mi Ierusalem impan im en sip, me ad a Petesda ni lokaia en Ipru; im limau mi impa,',
        3: 'Me somau toto mi lole: Me maskun, o me dangidang, o me motor mia, auiaui lao pil o pan mokimokid.',
        4: 'Pwe akai ansau tounlang amen kin koti dong le o kamokideda pil o, a meamen me madang tiong mas nan pil o ni a mokimokid, iei me kin maureda sang a somau kan karos, me mi re a.',
        5: 'A aramas amen mia, me somauki par sileisokwalu.',
        6: 'Iesus lao kotin masani men et a wonon, ap kotin mangi, me a wonon ansau warai, ap kotin masani ong i: Koe so men kelailada?',
        7: 'Ol somau potoan ong i: Maing, sota nai aramas, me pan wa ia di wong ni pil o ansaun a mokideda. Pwe ni ai kokodi, amen kin madang mo i.',
        8: 'Iesus ap kotin masani ong i: Uda, ale ki om, kokowei!',
        9: 'Aramas o ap madang kelailadar, kida ki e, alu wei, a ran o ran en sapat.',
        10: 'Sus oko ap indai ong me kelailadar: Ran wet ran en sapat. A sota pung koe en wewa sili ki om.',
        11: 'A sapeng irail: Me kakela ia da, masani ong ia: Ale ki om koko wei!',
        12: 'Irail ap kalelapok re a: Is aramas o me indai ong uk: Ale ki om kokowei?',
        13: 'A me kelailadar sasa i, pwe Iesus kotila sanger, pwe pokon mi wasa o.',
        14: 'Kadekadeo Iesus kotin diaradar i nan im en kaudok o ap kotin masani ong i: Kilang, koe kelailadar, koe der pil wia dip, pwe me sued kot sang mas de ko dong uk!',
        15: 'Aramas o ap koieila, kaireki Sus oko, me Iesus kakeladar i.',
        16: 'I me Sus oko ap raparapaki Iesus, o masamasan, pwen kamela i, pweki a kotin wiadar meakan ni ran en sapat.',
        17: 'Iesus kotin sapeng irail: Sam ai kin dodok kokodo, a ngai pil iang dodok.',
        18: 'I me Sus oko ap masamasan melel, en kamatala i, pweki a kotin kawela ran en sapat o pil masani, me dene Kot Sam a, o a kaparoki ong pein i Kot.',
        19: 'Iesus ap kotin sapeng masani ong irail: Melel melel I indai ong komail, a sota kak, Na en pein wia meakot, pwe i eta, me a kilang ren Sam, me a wiada. Pwe me a kin wiada, iei me Na pil kin wiada.',
        20: 'Pwe sam pok ong Na o kasansale ong i karos, me pein i kin wiada. O a pan kasale ong i wiawia kan, me lapa sang met akan, pwe komail en puriamui kila.',
        21: 'Pwe duen Sam kin kapikapirida me melar akan, kamaur ir ada, iduen Na pil kamaureda me a mauki.',
        22: 'Pwe sota me Sam kin kadeikada, pwe a kotiki ong Na kadeik o.',
        23: 'Pwe karos en wauneki Na, dueta ar wauneki Sam. Me sota wauneki Na, sota kin wauneki Sam, me kadar i dor.',
        24: 'Melel, melel I indai ong komail, meamen rong ai padak o poson, me kadar ia do, a aneki maur soutuk. A a sota pan pangalang kadeik o, pwe a sapale sang mela sapal ong maur.',
        25: 'Melel, melel I indai ong komail, ansau kokodo, iei a leler, me melar akan pan rongada ngil en Nain Kot, a me rongadar pan maureda.',
        26: 'Pwe duen Sam a udan maur, iduen a ki ong Na, en pil udan maur.',
        27: 'O a kotiki ong i manaman, en kaunda kadeik o, pweki Nain aramas i.',
        28: 'Der puriamuiki met, pwe ansau kokodo me irail, me mi nan sousou kan, pan rong ngil a.',
        29: 'Irail ap pan pwarada: Me wiadar me mau, en maureda, pwen memaur, a me wiadar mesued, en maureda, pwen pangalang kadeik o.',
        30: 'Sota me I kak wiada sang pein ngai, duen me I kin rong, iduen I kin kadeikada, o ai kadeik me pung, pwe I sota kin rapaki insen ai, pwe kupur en i, me kadar ia do.',
        31: 'Ma I kadede pein ngai, ai kadede sota melel.',
        32: 'Amen me kadede ia, a I asa melel, me a kadede ia me melel.',
        33: 'Komail me ilakilang Ioanes, i ari me kadede melel.',
        34: 'A I sota kin ale kadede ren aramas, a iet me I indawei, pwe komail en dorola.',
        35: 'I me ser umpul o marain eu, a komail men perenki a marain ansau kis.',
        36: 'A ai kadede me lapa sang en Ioanes. Pwe dodok kan, me Sam o kotiki ong ia, I en kapwaiada, iei dodok kan, me I kin wiawia, me kadede ia, me Sam kadar ia dor.',
        37: 'A Sam, me kadar ia dor, pein i kadede ia. Komail sota rongadar ngil a, o sota kilang mom a.',
        38: 'O a masan sota kin kot re omail, pwe komail sota poson, me a kadarador.',
        39: 'Komail kin kalelapok nan kisin likau kan, pwe komail lamelame, me maur soutuk mi lole. Ari, iei irail, me kin kadede ia.',
        40: 'A komail kang ko dong ia, pwe komail en aneki maur.',
        41: 'I sota kin mauki ale wau ren aramas akan.',
        42: 'I asa komail, limpok en Kot sota kin mi re omail.',
        43: 'I kodo ni mar en Sam ai, a komail sota kin kasamo ia. A ma amen pan kokido pein ad a, komail pan kasamo i.',
        44: 'Pala komail kak poson ni omail ngongongki wau ren aramas, ap sota rapaki wau sang ren Kot.',
        45: 'Der kiki ong, me I pan mpäkin komail ren Sam, amen me kin mpäkin komail: Moses, me komail kin kaporoporeki.',
        46: 'Pwe ma komail posonla Moses, komail pan poson ia, pwe i me intingiedier duen ngai.',
        47: 'A ma komail so kamelele a inting kan, pala komail pan kamelele ai padak kan?',
    },
    6: {
        1: 'MURIN mepukat Iesus kotin kotela le en Tiperias nan Kaliläa.',
        2: 'A pokon kalaimun me idedauen i pweki ar kilanger kilel akan, me a kotin wiai ong me somau kan.',
        3: 'Iesus ap kotidala pon dol o, kaipokedi wasa o ren sapwilim a tounpadak kan.',
        4: 'A pasa o, ran lapalap en Sus oko me korendor.',
        5: 'Iesus lao kotin masanda masani pokon kalaimun koko dong i, ap kotin masani ong Pilipus: Ia wasa, sen neti sang ia kisin manga, pwe mepukat en manga?',
        6: 'A kotin masani mepukat, pwen kasongesong i. Pwe pein i mangi, me a pan wiada.',
        7: 'Pilipus potoan ong i: Prot me denar riepuki sota pan itar ong irail, pwe amen amen en tungole ekis.',
        8: 'Andreas, sapwilim a tounpadak amen, ri en Simon Petrus potoan ong i:',
        9: 'Kisin putak amen mia, me a lopon en prot limau o mam riamen, a sota katepa ren me toto.',
        10: 'Iesus kotin masani: Kamod ong irail edi! Ari, wasa o me reen. Impan ol limekid ap mondi.',
        11: 'Iesus ap kotikida lopon ko, a lao laolaoki, ap kotin nek ong irail me mondier, pil dueta mam oko, irail lao metilar.',
        12: 'Irail lao metier, a kotin masani ong sapwilim a tounpadak kan: Ki pena me lua, pwe ekis der lokidokila!',
        13: 'Irail ap ki pena kopou eisokriau kisan lopon ko, me luadi murin arail manga.',
        14: 'Aramas akan lao kilanger kilel o, me Iesus kotin wiadar, re ap indada: Melel i Saukop o, me pan pwara dong sappa.',
        15: 'Iesus lao kotin mangi, me re pan poto dong i, pwen kasapwiladang i Nanmarki, ap pil kotidalang nin dol o, kotin kelepala.',
        16: 'A lao sautik pena, sapwilim a tounpadak kan ap kotilang ni oror,',
        17: 'Kereda pon sop pot, kotela kokolang Kapernaum. A lao wasa pongier, Iesus saikenta iang irail.',
        18: 'A sed me iluken, pwe ang me ma.',
        19: 'Irail seisei kila mail eisoklimau de rieisok, rap kilangada Iesus a kotikotido pon sed koren iong sop, irail ap masapwekadar.',
        20: 'A kotin masani ong irail: Ngai i komail der masak!',
        21: 'lrail ap men kasamo i pon sop o, a sop o madang milar ni sap o, me re ko ong ia.',
        22: 'A mandan ran o pokon o, me mi palilan le, lao kilanger, me sota apot sop mi wasa o, pwe i eta, me sapwilim a tounpadak kan keredang poa, o me Iesus sota iang sapwilim a tounpadak kan kotidang pon sop o, pwe a tounpadak kan kola kelep.',
        23: 'A pil akai kisin sop me pwarado sang Tiperias, tanga dong wasa o, me re mangamanga ia, murin Kaun o kotin laolao.',
        24: 'Aramas akan lao kilanger, me Iesus solar kotikot ia, o sapwilim a tounpadak kan pil so, rap dake sop pot kolang Kapernaum, raparapaki Iesus.',
        25: 'Irail lao diaradar i palilan le, ap potoan ong: Rapi iad me re kotido?',
        26: 'Iesus kotin sapeng irail masani: Melel, melel I indai ong komail, komail kin rapakin ia kaidin pweki kilel akan, me komail kilang, a pweki komail kangala kisin prot ap metier.',
        27: 'Komail der dokki manga, me kin ola, a dokki manga me kin mimieta ong maur soutuk, me Nain aramas pan ki ong komail, pwe i me Kot Sam kileledier.',
        28: 'Irail ap potoan ong i: Da me sen wiada, pwen kapwaiada en Kot a dodok kan?',
        29: 'Iesus kotin sapeng masani ong irail: Iet en Kot a dodok: Komail en poson i, me a kadarado.',
        30: 'Irail ari potoan ong i: Kilel da, me re kotikida, pwe sen kilang o poson ir? Da me re kotin wiada?',
        31: 'Sam at akan me kangala mana nan sap tan o, duen a intingidier: A kotiki ong irail prot sang nanlang, en kangala.',
        32: 'Iesus ap kotin masani ong irail: Melel, melel I indai ong komail, kaidin Moses, me ki ong komail prot sang nanlang, a Sam ai kin ki ong komail prot melel sang nanlang.',
        33: 'Pwe me kodido sang nanlang, o ki ong sappa maur, iei prot en Kot.',
        34: 'Irail ap indang i: Maing, kotiki dong kit prot wet kaukaule!',
        35: 'Iesus kotin masani ong irail: Prot en kamaur ngai, me ko dong ia solar pan men mangadar, o me poson ia, solar men nim piladar.',
        36: 'A I indai ong komail er, komail kilang ia er, ap so poson la.',
        37: 'Karos me Sam ki ong ia, pan ko dong ia, a me ko dong ia, I sota pan kasela.',
        38: 'Pwe ngai kodido sang nanlang, kaidin pwen wiada insen ai, pwe kupur en i, me kadar ia do.',
        39: 'Pwe iet kupur en me kadar ia do, karos me a ki ong ia er, I ender kasela amen, pwe I en kamaureda ni ran nik o.',
        40: 'A iet kupur en Sam ai, amen amen, me kin kilang Na o poson i, en aneki maur soutuk, a I pan kamaureda i ni ran nik o.',
        41: 'Sus oko ap lipanedeki i, pweki a kotin masani: Ngai prot, me kodi sang nanlang.',
        42: 'Irail indada: Kaidin i Iesus nain Iosep? A sam a o in a se asa. Ari, daduen a indada: I kodido sang nanlang?',
        43: 'Iesus kotin sapeng masani ong irail: Komail der lipaned nan pung omail!',
        44: 'Sota me pan kak ko dong ia, ma Sam, me kadar ia dor, sota kainongido i. A I pan kamaureda i ni ran nik o.',
        45: 'A intingidier nan saukop akan: Irail karos pan ale padak sang ren Kot. Amen amen me rongadar o padakki ren Sam, kin ko dong ia.',
        46: 'Ari, kaidin pweki meamen kilang Sam; i eta, me kodo sang ren Kot, i me kilanger Sam.',
        47: 'Melel, melel I indai ong komail, me poson ia, iei me aneki maur soutuk.',
        48: 'Prot en maur ngai.',
        49: 'Sam omail oko, me kangala mana nan sap tan o, ir ari melar.',
        50: 'Met prot, me kodido sang nanlang, meamen kin kang sang i, sota pan mela.',
        51: 'Ngai prot maur, me kodido sang nanlang, meamen kang sang prot wet, pan memaur kokolata. Prot, me I pan kida, iei uduk ai, me i pan kida en kamaur kida sappa.',
        52: 'Sus oko ari akamaiki pena indada: Iaduen men et pan kak ki ong kit uduk a sen kang?',
        53: 'Iesus ap kotin masani ong irail: Melel, melel I indai ong komail, ma komail sota pan kang uduk en Nain aramas o nim nta, sota maur omail.',
        54: 'Me kin kang uduk ai o nim nt’ ai, iei me aneki maur soutuk, a I pan kamaureda i ni ran nik o.',
        55: 'Pwe manga melel uduk ai, o pil melel nt’ ai.',
        56: 'Me kin kang uduk ai o nim nt’ ai, iei me podidi ong ia o ngai podidi ong i.',
        57: 'Duen Sam ieias kadar ia do, o ngai memaureki Sam, iduen me kang uduk o nt’ ai, pan meaureki ngai.',
        58: 'Iet prot, me kodido sang nanlang, kaidin duen sam omail akan, me kangala mana ap mela, a meamen kin kang prot wet, pan memaur kokolata.',
        59: 'Mepukat a kotin masani wei nan sinakoke, ni a kotin kawewe nan Kapernaum.',
        60: 'Ari, me toto ren sapwilim a tounpadak kan, me rongadar mepukat indada: Padak pot et meid apwal! Is me kak rong?',
        61: 'Iesus lao kotin angi nan kupur a, me sapwilim a tounpadak kan lipanedeki mepukat, ap kotin masani ong irail: Komail makaraki mepukat?',
        62: 'A ma komail pan kilang Nain aramas kodala wasa, me a kauson ia mas o?',
        63: 'Ngen me kin kamaureda, a uduk sota katepa. Padak kan, me I kin padapadaki ong komail, iei Ngen o maur.',
        64: 'A akai mi re omail, me so poson. Pwe Iesus kotin mangi, me so poson o me pan pangala i.',
        65: 'A kotin masani: I me I indaki ong komail, sota me kak ko dong ia, ma Sam sota kainongido.',
        66: 'Sang ni ansau o sapwilim a tounpadak kan toto mueiwei sang o solar idauen i.',
        67: 'Iesus ap kotin kainoma ren ekriamen oko: Komail pil pan kola?',
        68: 'A Simon Petrus ap sapeng i: Maing, is me se en ko ong? Pwe ar masan akan iei maur soutuk.',
        69: 'A kit posonlar o asaer, me ir me Saraui en Kot.',
        70: 'Iesus kotin sapeng irail: Kaidek komail ekriamen, me I piladar, a amen komail me tewil amen.',
        71: 'A kotin masaniada duen Iudas Iskariot nain Simon, pwe i amen ren ekriamen oko, me pan pangala i.',
    },
    7: {
        1: 'MURIN mepukat Iesus kotin kakan sili Kaliläa, pwe a solar men kakan sili Iudäa, pweki Sus oko masamasan kamatala i.',
        2: 'A ran lapalap en Sus oko; iei ran en im en tan tuka korendor.',
        3: 'Ri a ol akan ap indai ong i: Kom kotiwei kotilang Iudäa, pwe omui tounpadak kan en pil udial omui wiawia kan, me kom kin wiawia.',
        4: 'Pwe sota me kin wiada meakot wasa rir, ma a men indand sili. Ma komui wia mepukat, en kasansale ong sappa.',
        5: 'Pwe ri a ol akan pil sota poson i.',
        6: 'Iesus ap kotin masani ong irail: Ai ansau saikenta leler, a omail ansau mia ansau karos.',
        7: 'Sappa sota kak kailongki komail, a ngai me a kin kailongki, aki I kin kadede, me a wiawia kan me sued.',
        8: 'Komail kodalang kamadip et, I sota pan kodalang kamadip et, pwe ai ansau saikenta leler.',
        9: 'A kotin masani ong irail mepukat, ap kotikotita Kaliläa.',
        10: 'A ri a ol akan lao samalar, i ap pil kotidalang kamadip, ap so sansal a duen me rir.',
        11: 'Sus akan ari rapaki i ni kamadip o indada: Ari, ia wasa a kotikot ia?',
        12: 'A aramas akan lokolokaia toto duen i, pwe akai indada: Me mau men. A akai me indada: Kaidin, pwe a kin kaweid sapung aramas.',
        13: 'Sota me lokaia sansal duen i, pweki ar masak Sus oko.',
        14: 'Lao lel ailepan kamadip o, Iesus ap kotin kodalang im en kaudok o kaukaweweda.',
        15: 'A Sus akan ap puriamui kila indada: Da duen men et asa wewe en kisin likau, pwe a sota iang padakki.',
        16: 'Iesus ap kotin sapeng irail masani: Kaidin ai padak, me I kin kida a en me kadar ia do.',
        17: 'Meamen wiawia kupur a, pan weweki ai padak, ma a ren Kot, de sang ren pein ngai.',
        18: 'Me kin padapadak sang ni pein i, kin rapaki pein wau i, a me kin rapaki wau en me kadarala i, iei me melel o sota man sued kot pit.',
        19: 'Kaidin Moses, me ki ong komail kapung o, a sota amen komail kin kapwaiada kapung o? A da me komail rapakiki kame ia la?',
        20: 'Aramas oko sapeng indada: Koe me tanwar en tewil, is me rapaki kame uk ala?',
        21: 'Iesus kotin sapeng masani ong irail: Dok taieu, me I wiadar, a komail puriamui kila.',
        22: 'Moses ki ong komail er sirkomsais, a kaidin tapi sang ren Moses, pwe sang ren sam akan, a komail kin sirkomsais aramas ni ran en sapat.',
        23: 'Ari ma aramas amen ale sirkomsais ni ran en sapat, pwe kapung en Moses ender sapungala, a komail kin suede kin ia, pweki ai kakelailada aramas pon ni ran en sapat?',
        24: 'Der kadeikada duen pali liki, a komail kasaui nin tiak en kadeik pung.',
        25: 'Men Ierusalem kai ap inda: Kaidin i, me re raparapaki en kamela?',
        26: 'A kilang, a padapadak sansal, a re sota man lokaia ong i, de muein saumas akan asaer mau, me i Kristus?',
        27: 'Ari, se asaer, wasa men et ko sang ia, a Kristus lao kotido sota me pan asa wasa, me a pwarado sang ia.',
        28: 'Iesus ap kotin kapitie laudeda kawewe nan im en kaudok masani: Komail asa ia o wasa I ko sang ia. Ari, kaidin pein ngai, me I kokido, a me kadar ia dor, me melel, me komail sasa.',
        29: 'A I asa i, pwe I kodo sang re a, o i me kadar ia dor.',
        30: 'Irail ap song saikidi i, a sota me sair i, pwe a ansau kaikenta leler,',
        31: 'Aramas toto sang nan pokon o posonla i indada: Iaduen, Kristus lao pwarado, a pan wia kilel toto sang mepukat, me men et wiadar?',
        32: 'Parisär akan rongadar, me aramas akan lokelokaia mepukat duen i. Samero lapalap o Parisär akan ap kadarala papa kan, en saikidi i.',
        33: 'Iesus ap kotin masani: I pan mi re omail ansau motomot. I ap pan kola ren me kadar ia do.',
        34: 'Komail pan rapakin ia, ap sota diar, a wasa, me I pan mi ia, komail sota pan kak ong.',
        35: 'Sus oko ap inda nan pung arail: A pan kola ia, pwe sen solar diar i? A pan kola ren me salongalar ren men Krik kan, kaukawewe ong men Krik?',
        36: 'Iaduen masan en, me a indada: Komail pan rapakin ia, ap sota diar, a wasa, me I pan mi ia, komail sota pan kak ong?',
        37: 'Ni ran en kamadip a nikilar, ni ran lapalap o, Iesus kotida, kapitie laudeda masani: Meamen men nim piladar, i en ko dong ia nim.',
        38: 'Me poson ia, duen kisin likau kan indada, sang nan war a pil memaur pan pwilipwili sang ia.',
        39: 'Mepukat a kotin masani duen Ngen, me irail, me poson i, en tungole; pwe Ngen saikenta pakadarado, aki Iesus saikenta linganlar.',
        40: 'Ari, akai sang nan pokon o ni ar rongadar masan pukat ap indada: Melel Saukop o.',
        41: 'A akai indada: Kristus men et! A akai indada: Da, Kristus pan pwarado sang Kaliläa?',
        42: 'Kaidin kisin likau me inda, me Kristus pan wan Dawid o kisan men Petleem, kanim o, me Dawid kotikot ia?',
        43: 'Irail ap liak toror pasang pweki i.',
        44: 'A akai men saikidi i, a sota me sair i.',
        45: 'A papa ko ap pure dong ren samero lapalap o Parisär akan. Irail ari idok re irail: Da me komail sota wakido?',
        46: 'A papa ko sapeng: Sota man aramas amen padapadak duen men et.',
        47: 'Parisär oko ap sapeng irail: Komail pil pakodauelar?',
        48: 'Iaduen saumas de Parisär amen posonla i?',
        49: 'A aramas pukat, me so asa kapung o, re rialar.',
        50: 'Nikodemus kis arail ap indang irail:',
        51: 'Iaduen, atail kapung pil kin kadeikada aramas amen mon a rong o asa sang pein i duen a wiawia?',
        52: 'Irail sapeng indang i: Iaduen, komui pil kisan men Kaliläa? Rapaki o kilang, me sota saukop amen ko sang Kaliläa.',
        53: 'Amen amen ap purelang deu a.',
    },
    8: {
        1: 'IESUS ap kotidala pon dol Oliwe.',
        2: 'A nin soran a kotin pure dong ong nan im en kaudok. Aramas karos ap pokon dong i. I ari kaipokedi kaukawewe ong irail.',
        3: 'A saunkawewe o Parisär akan wa dong i li amen, me diarokadar ni a kamal. Irail kidang i nan pung arail.',
        4: 'Ap indang i: Saunpadak, li men et diarokadar ni a kamal.',
        5: 'A Moses masani ong kitail nan kapung o, sen kate song en. A komui, da me komui masani?',
        6: 'A mepukat re indang i, pwen kasongesong i, pwe ren kak impimpaiki i meakot. A Iesus kotin idiokidi, intingiekidi ong nani pwel sondin lim a.',
        7: 'A ni ar poden kalekalelapok re a, a ap kotin dengida masani ong irail: Ari, me sota dip a nan pung omail, a pan tapiada kate i.',
        8: 'A pil kotin idiokidi intingiedi ong nan pwel.',
        9: 'Irail lao rongadar met, rap mulikidar tentelwei, me laud mas lel me tikitik o. A Iesus kelepela, li eta, me mi re a.',
        10: 'Iesus lao kotin dengida o sota masani meamen, li eta, ap masani ong i: Ia me karaun uk edi kan? Sota me kadeik uk ada?',
        11: 'A potoan ong: Sota Maing. Iesus ap kotin masani ong i: I sota pil pan kadeik uk ada. Kowei, koe der pil wiada dip!',
        12: 'Iesus ap pil kotin padaki ong irail masani: Ngai marain en sappa. A me kin idauen ia, sota pan weid ni rotorot, pwe marain en maur pan mi re a.',
        13: 'Parisär oko ap indai ong i: Komui kadede pein komui; ari, omui kadede sota melel.',
        14: 'Iesus kotin sapeng masani ong irail: Ma I kadede pein ngai, ari melel ai kadede, pwe I asa, wasa I kodo sang ia o wasa I koko ong ia, a komail sasa, wasa I ko sang ia o wasa I koko ong ia.',
        15: 'Komail kin kadeikada duen pali uduk, a sota meamen, me I kin kadeikada.',
        16: 'Ari so ma I kadeikada, ai kadeik pan melel, pwe I sota kin kelep, pwe ngai o Sam, me kadar ia dor.',
        17: 'A pil intingidier nan omail kapung, me kadede en aramas riamen me melel.',
        18: 'Ngai me kin kadede pein ngai o Sam, me kadar ia dor, kin kadede ia.',
        19: 'Irail ap indai ong i: Ia Sam omui? Iesus kotin sapeng: Komail sota asa ngai, pil sota Sam ai. Ma komail asa ia, komail pil pan asa Sam ai.',
        20: 'Masan pukat Iesus kotikida nan pera en moni, ni a kotin kaukawewedar nan im en kaudok o. A sota me koledi i, pwe a ansau saikenta leler.',
        21: 'Iesus pil kotin masani ong irail: I kokola, a komail pan rapakin ia o mela ni omail dip akan, a wasa, me I pan kola ia, komail sota pan kak ong.',
        22: 'Sus oko ap indada: A pan kamela pein i, pweki a inda: A wasa, me I pan kola ia, komail sota pan kak ong?',
        23: 'A kotin masani ong irail: Komail kisan men pa, a ngai kisan men poa. Komail kisan sappa et, a ngai kaidin kisan sappa et.',
        24: 'Iei me I indaki ong komail, komail pan mela ni omail dip akan, pwe ma komail sota kamelele ia, komail pan mela ni omail dip akan.',
        25: 'Irail ap indai ong i: Is koe? Iesus kotin masani ong irail: Me I indawei mas o, i eta.',
        26: 'Me toto I men padaki ong komail o kadeikada, ari so, me kadar ia do me melel. A I kin kasoia ong komail, me I rongadar re a.',
        27: 'Irail ari sasa, me a kotin kasoia ong irail duen Sam a.',
        28: 'Iesus ap kotin masani ong irail: Komail lao kauadar Nain aramas, komail ap pan asa, me ngai i, o me I sota wia meakot sang pein ngai. A duen Sam, me padaki ong ia er, iduen I kin kasoia wei.',
        29: 'Me kadar ia do, kin ieiang ia, a sota lokit ia la, pwe I kin potin wia, me a kupura mauki.',
        30: 'Ni a kotin masani mepukat, me toto ap posonla i.',
        31: 'Iesus ap kotin masani ong Sus oko, me poson i: Ma komail pan podidi ong ai padak, nan ai tounpadak melel komail.',
        32: 'O komail pan asala melel, o melel pan kamaio komail da.',
        33: 'Irail sapeng i: Wan Apraam kit, sota me se lidui sang mas kokodo. A iaduen, komui indada: Komail pan maioda?',
        34: 'Iesus kotin sapeng irail masani: Melel, melel I indai ong komail, meamen; me wiawia dip, i me ladun dip.',
        35: 'A ladu o sota pan mimieta nan im o, na eta pan mimieta.',
        36: 'Ari, ma Na pan kamaio komail da, komail pan maioda melel.',
        37: 'I asa, me wan Apraam komail, a komail kin rapaki, en kame ia la, pwe ai padak sota kin podidi ong komail.',
        38: 'Me I kilang ren Sam ai, iei me I inda wei, a komail kin wiawia, me komail rongada ren sam omail.',
        39: 'Irail sapeng indang i: Sam at Apraam. Iesus kotin masani ong irail: Ma komail nain Apraam, seri kan, komail pan wia duen en Apraam a wiawia kan.',
        40: 'Ari, met komail kin rapaki kame ia la, aramas amen, me kasoi ong komail melel, me I rongadar ren Kot, i me Apraam sota wiadar.',
        41: 'Komail kin kapwaiada wiawia kan en sam omail. Irail ap indang i: Kaidik kit ipwin nenek. Sam at me ta men Kot.',
        42: 'Iesus kotin masani ong irail: Ma Kot Sam omail, komail pan pok ong ia, pwe I kodo sang ren Kot, kaidik sang pein ngai, me I kokido, pwe i me kadar ia do.',
        43: 'Da me komail sota weweki ai padak? Pweki omail sota kak rong ai padak.',
        44: 'Komail tapi sang ren sam omail tewil, o inong en sam omail, me komail men wiada. Nan i men kamela men sang ni tapi o, o a sota dadaurata melel, pwe sota man melel mi re a, ni a lalal likam, a kin kida sang pein audepa, pwe i me likam men o sam en likam o.',
        45: 'A komail sota kamelele ia, pweki I padaki ong komail melel.',
        46: 'Is re omail, me kak indang ia, me dip ai mia? A ma I kasoi melel, menda komail so poson?',
        47: 'Men ren Kot kin rong en Kot a masan akan. Komail ari sota rong, pwe kaidin me ren Kot komail.',
        48: 'Sus oko sapeng indang i: Kaidik meid melel, koe men Samaria amen o tanwar en tewil.',
        49: 'Iesus kotin masani: Kaidik tanwar en tewil ngai, pwe I wauneki Sam ai, a komail kin kisang ia wau i.',
        50: 'I sota kin rapaki pein wau i, amen mia, me kin raparapaki o kadeikada.',
        51: 'Melel, melel I indai ong komail, meamen kapwaiada ai padak, sota pan mela kokolata.',
        52: 'Sus oko ap indai ong i: Se ap asaer, me koe tanwar en tewil. Apraam melar, pil saukop akan, a koe me inda: Meamen kapwaiada ai padak, sota pan mela kokolata,',
        53: 'Da, komui me lapa sang sam at Apraam, me matalar, pil saukop akan, me matalar? Is me komui pein wia kin uk?',
        54: 'Iesus kotin sapeng: Ma I pein kaka kin ia, ai kaka me mal. A Sam ai, me kaka kin ia, me komail kin inda: I atail Kot.',
        55: 'Komail ari kaikenta asa i, a I asa i, a ma I inda, me I sasa i, I pan me likam amen dueta komail. A I asa i o kapwaiada a masan akan.',
        56: 'Sam omail Apraam peren kida, me a pan kilang ai ran. I ari kilanger ap peren kidar,',
        57: 'Sus oko ap indang i: Par limeisok kaik dau po’mui, a kom kilanger Apraam?',
        58: 'Iesus kotin masani ong irail: Melel, melel I indai ong komail, I mier mon Apraam.',
        59: 'Irail ap rik takai, pwen kasuk i, i ap kotin oki sang irail pein i, kotila sang nan im en kaudok o.',
    },
    9: {
        1: 'IESUS lao kotin daulul, ap masani aramas amen me maskun sang a ipwidi.',
        2: 'Sapwilim a tounpadak kan ap idok re a potoan ong: Rapi, is me wiadar dip, i de sam a in a, pweki a ipwidi maskun?',
        3: 'Iesus kotin sapeng: Kaidik i me wiadar dip, pil kaidik in a de sam a, a pwe en Kot a wiawia kan en kasansal kida i.',
        4: 'I en kapwaiada wiawia kan en me kadar ia do arain ansaun ran, pwe pong pan kodo, i ansau solar amen kak dodok.',
        5: 'Arain ai mi sappa, ngai marain en sappa.',
        6: 'A lao kotin masanier met, ap likidi nani pwel, wiakida pwel madak iriski mas a.',
        7: 'Masani ong i: Kolang pil en Siloa (iet wewe: Pakadarado), opinok ia! I ari kola opinok, ap puredo kilangada wasa.',
        8: 'A men imp a kan, o me iang kilangadar, me a men poekipoek amen mas o, rap indada: Kaidik i, me wonon poekipoeki?',
        9: 'Akai me inda: I met; a akai me inda: Likamata i, a pein i indada: Ngai i.',
        10: 'Irail ari indang i: Iaduen por en mas om akan a kapad pasang?',
        11: 'A sapeng indada: Aramas amen me adaneki Iesus, me wiadar pwel madak, iriski mas ai, masani ong ia: Kolang pil en Siloa, opinok ia! I ari kola opinok, ap kilangada wasa.',
        12: 'Irail ap idok re a: Ia i? A sapeng: I sasa.',
        13: 'Irail ap kalualang ren Parisär akan me maskun mas.',
        14: 'Ari, ni ran en sapat, me Iesus kotin wiadar pwel, kapad pasang por en mas a kan.',
        15: 'Parisär akan pil idok duen me a kilang kida wasa. A sapeng irail: A ki ong pwel ni por en mas ai, i ap opinok, ngai ari kilangada wasa.',
        16: 'Parisär kai ap inda: Aramas men et kaidik men ren Kot, aki a sota apwali ran en sapat. Akai indada: Daduen, aramas dipan amen kak wia kilel pukat? Irail ari liak toror pasang.',
        17: 'Irail pil kalelapok ren me maskun o: Da me koe lamelame duen i? Pwe a kapad pasang mas om? A sapeng: Saukop amen i.',
        18: 'Men Sus oko ap sota kamelele, me a ipwiki wei maskun, ap kilangada wasa. Irail lao ekeredo sam o in en me kilangada wasa.',
        19: 'Irail idok re’ra: Nouma ol men et, me komail indinda, me a ipwiki wei maskun? Iaduen a ngarada wasa ansau wet?',
        20: 'Sam a in a sapeng ir indada: Se asa, me nait ol et, me ipwiki wei maskun.',
        21: 'A se sasa duen a ngarada wasa o me kapad pasang por en mas a. A malar, kainoma re a, a pan pein sakaraki i.',
        22: 'Sam o in a inda mepukat, pweki ar masak Sus oko. Pwe Sus oko inauki pena, ma meamen pan kadede me i Kristus a pan lokidokila sang nan sinakoke.',
        23: 'I me sam o in a indada kida: A malar, kainoma re a.',
        24: 'Irail ap eker aramas maskun kariapak indai ong i: Wauneki Kot, se asa, me aramas men et me dipan amen,',
        25: 'A sapeng ir indada: I sasa, ma i me dipan amen de so. I eta me i asa, me ngai me maskun mas o, i ap potoan ngaradar wasa.',
        26: 'Irail ap pil idok re a: Da me a wiai ong uk? Iaduen a kapad pasang mas om?',
        27: 'A sapeng irail: I indai ong komail er, a komail sota rong? Da me komail pil men rongki? Komail pil pan a tounpadak ala?',
        28: 'Irail kaurureki indada: A tounpadak amen koe, a kit tounpadak en Moses akan.',
        29: 'Kit asa, me Kot masani ong Moses. A lap o se sasa, wasa a ko sang ia.',
        30: 'Aramas o sapeng indang irail: Meid kapuriamui! I me kapad pasang mas ai kat, a komail sasa, wasa a koti sang ia.',
        31: 'Kitail asa, me Kot sota kin mangi me dipan akan. A meamen, me lan Kot, o dadaurata kupur a, iei me a kin kotin mangi.',
        32: 'Sang mas kokodo sota me rongadar, me meamen kapad pasang mas en me ipwiki wei maskun.',
        33: 'Ma men et sota me ren Kot, a sota pan kak wia meakot.',
        34: 'Irail sapeng indang i: Koe me ipwiki wei dip akan a koe ap padaki ong kit? Irail ari kasela i.',
        35: 'Iesus lao kotin mangidar, me re kasela i, a lao masani i, ap kotin masani ong i: Koe kin poson Nain Kot?',
        36: 'A sapeng potoan ong: Maing, is i pwe i en poson i?',
        37: 'Iesus kotin masani ong i: Koe me kilang i. A iet i, me kasokasoi ong uk.',
        38: 'A sapeng i: Maing, i posonlar, i ari kaudok ong i.',
        39: 'Iesus kotin masani: I kodon kadeik nan sappa et, pwe me so kilang wasa, en kilangada, a me kilang wasa, en maskunla.',
        40: 'A Parisär akan, me mi re a, rongadar a masan pukat, re ap peidok re a: Da, kit me pil maskun?',
        41: 'Iesus kotin masani ong irail: Ma komail maskun, sota pan dip omail. A komail indada: Se kilekilang wasa, iei me omail dip pan mimietaki.',
    },
    10: {
        1: 'MELEL, melel I indai ong komail, me so weid nan wanim, pedelong ong nan deun sip, a dauda wasa toror, iei men lipirap o men kuli.',
        2: 'A me kin pedelong pan wanim, iei silepan sip o.',
        3: 'Iei me silepan wanim o kin ritingada mo a; a sip akan kin rong ngil a; i me ekereki na sip akan ad arail, kare irail wei.',
        4: 'A kin kapedoi na sip akan, ap tiong mo’rail, o sip akan kin idedauen i, pwe re anlar ngil a.',
        5: 'A re sota pan idauen, me re san, pwe re pan tang sang, pwe re san ngil arail.',
        6: 'Iesus kotin masani ong irail karaseras pot et, a irail sota weweki mepukat, me a kotin masani ong irail.',
        7: 'Iesus pil kotin masani ong irail: Melel, melel I indai ong komail: Ngai wanim en sip akan.',
        8: 'Karos, me pwarador mo i, iei lipirap o men kuli, o sip akan sota kin rong irail.',
        9: 'Ngai wanim o, a meamen pedelong re i, pan kamaurela o diar manga purepure.',
        10: 'Lipirap kin kodon pirapela, o kamela, o kaokaoe, a ngai kodo, pwe irail en ale maur, kakairida kokolata.',
        11: 'Ngai silepa mau; a silepa mau kin tonmeteki ong na sip akan maur i.',
        12: 'A me kin pwaipwai o me sota udan silepa, o me kaidin udan na sip oko, iei me ngingar kidi en wel kokodo, ap kasela sip oko, tangdaui, a kidi en wel saikidi sip oko, kamueit ir pasang.',
        13: 'Me pwaipwai o kin tangdaui, aki a pwaipwai, o sota insenoki sip oko.',
        14: 'Ngai silepa mau, o I asa nai kan, o nai kan pil asa ia.',
        15: 'Duen Sam o asa ia, iduen I asa Sam, o I tonmeteki ong sip akan maur i.',
        16: 'A pil akai nai sip, me so kisan nan kel wet, mepuko I pil pan wado, o re pan rong ngil ai, o a pan pwin taieu o silepa me ta men,',
        17: 'Iei me Sam pok ong ia, pwe I kidi maur i, pwe I en pur ong ale.',
        18: 'Sota me ki sang ia, pwe pein ngai kidi. I manaman ong kidi maur i, I pil manaman ong kapure dong ia. Kusoned pot et I aleer sang ren Sam ai.',
        19: 'Iei me Sus oko ap pil liak toror pasang pweki masan pukat.',
        20: 'Me toto re’rail indada: A tanwar en tewil o iakalar. Menda komail rong i?',
        21: 'Akai me indada: Kaidik padak en tanwar en tewil pukat, da, tewil pan kak kapad pasang mas en me maskun amen?',
        22: 'A ran en isimas en im en kaudok wiaui nan Ierusalem, i ansaun kapau.',
        23: 'A Iesus kotikot sili nan im en kaudok, nan palang en Salomo.',
        24: 'Sus oko kapili pena i indang i: Arai da komui pan okioki sang kit? Ma komui Kristus, en kadede ong kit sansal!',
        25: 'Iesus kotin masani ong irail: I indai ong komail er, a komail sota poson dodok kan, me I wiadar ni mar en Sam ai, iei me kin kadede ia.',
        26: 'A komail sota poson, pwe komail kaidik kisan nai sip, duen me I indai ong komail er.',
        27: 'Nai sip oko kin rong ngil ai, a I asa irail a re kin idauen ia.',
        28: 'A I ki ong irail maur soutuk, a re sota pan salongala kokolata, o sota, me pan ki sang irail nan pa i.',
        29: 'Sam ai, me ki ong ia irail, me lapa sang meakaros, o sota me pan kak ki sang irail ni lim en Sam ai.',
        30: 'Ngai o Sam me ta men.',
        31: 'Sus oko ap pil rik takai, pwen kasuk i.',
        32: 'Iesus kotin sapeng irail: Dodok mau toto, me I kasale ong komail er sang ren Sam o, a menia dodok ren mepukat, me komail kate kin ia?',
        33: 'Sus oko ap sapeng i: Kaidik dodok mau eu, me se kate kin komui, a pweki lalaue, o pweki aramas amen koe, me wia kin pein uk Kot,',
        34: 'Iesus kotin sapeng irail: A so intingidier nan omail kapung: I indada, komail kot akan,',
        35: 'Ari, ma a kin wia kin ir kot, me aleer masan en Kot, pwe kisin likau kan sota kak sapungala;',
        36: 'A komail kin inda kin i, me Sam a kasarauialar, o kadara dong sappa, koe lalaue, pweki ai indada: Sapwilim en Kot ngai?',
        37: 'Ma I so wiawia dodok kan en Sam ai, komail der kamelele ia.',
        38: 'A ma I kin wiawia, komail en posonki dodok kan, ma komail sota poson ia, pwe komail en asa o poson, me Sam ai podidi ong ia, o ngai podidi ong i.',
        39: 'Irail ap pil song saikidi i. I ari piti sang ni pa’rail.',
        40: 'O kotin purelang palilan Iordan, wasa Ioanes kin wia paptais ia mas; I ari kotikot wasa o.',
        41: 'A me toto pokon dong i indada: Ioanes sota wiadar kilel eu; a melel eta karos, me Ioanes masanieki men et.',
        42: 'A me toto posonla i wasa o.',
    },
    11: {
        1: 'OL amen somaudar ad a Lasarus, men Petanien, kanim en Maria o ri a li Marta.',
        2: 'Iei Maria, me keieki potik Kaun o, o limwieki a pwilipeipei aluwilu a, me ri a ol Lasarus somaudar.',
        3: 'Ri a li ko ari kadar wong i kaireki wong i: Maing, kotin mangi, me re pok ong me somaudar.',
        4: 'Iesus lao mangi, ap kotin masani: Kaidik somau en mela eu met, a pweki lingan en Kot, pwe Nain Kot en kalingana kila.',
        5: 'Iesus kotin kupura Marta, o ri a li, o Lasarus.',
        6: 'A lao kotin mangier, me a somaudar, i ari kotikoteta wasa o pong ria pong.',
        7: 'Ap kotin masani ong sapwilim a tounpadak kan: Kitail pan purelang Iudäa.',
        8: 'Sapwilim a tounpadak kan potoan ong i: Rapi, Sus oko apton men kasuk ir, a re pan kotin purelang ia?',
        9: 'Iesus kotin masani: So auer eisokriau ni ran eu? Meamen alialu ni ran, sota pan dipikelekel, aki a ngingar marain en sappa.',
        10: 'A meamen alialu ni pong, a pan dipikelekel, aki marain sota mi re a.',
        11: 'A kotin kasoiada mepukat, ap masani ong irail: Kompoke patail Lasarus mairelar, a I kokolan kapirida i.',
        12: 'A sapwilim a tounpadak kan indang i: Maing, ma a mairelar, a pan maureda.',
        13: 'Ari, Iesus kotin masanieda duen a melar, a irail kiki ong, me a masanieda duen a mair en kamol.',
        14: 'Iesus ap sansal masani ong irail: Lasarus melar,',
        15: 'A I peren kida, me I sota mi wasa o pweki komail, pwe komail en posonla. Ari, kitail en koko wei re a!',
        16: 'Tomas, me pil ad a Didimus, ap indai ong warok tei kan: Kitail en pil kokola, pwen iang i mela.',
        17: 'Iesus lao kotido, ap kotin diarada, me a mi nan sousou pong pa pong.',
        18: 'Petanien me koren iong Ierusalem impan mail riau.',
        19: 'A Sus oko me toto ko dong Marta o Maria, pwen kamait ira la pweki ri ara ol o.',
        20: 'Marta lao rongadar, me Iesus kotido, ap koieila tu ong i. A Maria momod nan im o.',
        21: 'Marta ap potoan ong Iesus: Maing, ma re kotikot met, ri ai ol sota pan mela.',
        22: 'Ari so, i asa meakot re pan kotin poeki ren Kot, Kot pan kotiki ong ir.',
        23: 'Iesus kotin masani ong i: Ri om ol pan maureda.',
        24: 'Marta potoan ong i: I asa, me a pan maureda ni ias en ni ran nik o.',
        25: 'Iesus kotin masani ong i: Ngai kamaur o maur, me poson ia, pan memaureta pil murin a mela.',
        26: 'A meamen me maur o poson ia, sota pan mela kokolata; koe kamelele mepukat?',
        27: 'A potoan ong i: Ei Maing, i poson, me ir me Kristus Sapwilim en Kot, me udan pwara dong sappa.',
        28: 'A lao indada met, ap koieila ren Maria ri a li, monginki ong i: Saunpadak kotidor kainoma uk.',
        29: 'A lao rongadar, ap uda, madang wei re a,',
        30: 'A Iesus saikenta lel ong kanim o, pwe a kotikoteta wasa Marta tu ong i ia.',
        31: 'Sus oko, me mi re a nan im o, pwen kamait i ala, lao kilangada, me Maria madang uda tang wei, rap idauenla i, indinda: A pan ko ong ni sousou, pwen sangesang ia.',
        32: 'Maria lao lel wasa o, o kilang i, ap poridi ong ni aluwilu a indang i: Maing, ma re kotikot met, ri ai ol sota pan mela.',
        33: 'Iesus lao masani i sangesang, o Sus oko, me iang i kokodo pil sangesang, ap kupurola,',
        34: 'Masani: Komail pwilikidi ia i? Irail potoan ong i: Maing, kotido masani.',
        35: 'Iesus kotin tontonir.',
        36: 'Sus oko ap inda: Kilang duen a pok ong i!',
        37: 'A akai ir me indada: A so kak pan men et me kapad pasang mas en me maskun o, me ol men et ender mela?',
        38: 'Iesus pil kupurola koti dong sousou o. A por o ulong nan kisin dol o takai eu mi poa.',
        39: 'Iesus kotin masani: Katapure wei takai en! A Marta, en me melar ri a li, indada: Maing, a matalar, pwe a mi met pong pa pong.',
        40: 'Iesus kotin masani ong i: I so indai ong uk, ma koe poson, koe pan kilangada lingan en Kot.',
        41: 'Irail ap katapure sang takai o. A Iesus kotin masanda masani: Sam, I danke komui, me komui mangi ia er.',
        42: 'A i asa, me komui kin mangi ia ansau karos, a pweki pokon o, me u sili, I indaki mepukat, pwe irail en poson, me komui, me kadar ia do.',
        43: 'A lao kotin masani met, ap kapitie laudeta masani: Lasarus, koieido!',
        44: 'A me melar o ap pedoido, likau en sousou kidim pena na o pa kan, o mas a me pirapinki pena lim en puto. A Iesus kotin masani ong irail: Lapwada kapitila i!',
        45: 'Men Sus toto, me ko dong Maria, o kilanger, me Iesus kotin wiadar, posonla i.',
        46: 'A akai ir kowei ren Parisär oko, kaire kin irail me Iesus kotin wiadar.',
        47: 'Samero lapalap o Parisär akan ap pokon pena kapung indada: Da me kitail en wiada? Pwe aramas men et kin wia kilel toto.',
        48: 'Ma kitail sota pan mokidi ong i, karos pan posonla i, o men Rom pan kodo, ki sang kitail wei o atail kainok.',
        49: 'A amen irail ad a Kaipas, me samoro lapalap ni par o, indang irail: Komail meid so lolekong.',
        50: 'O sota lamelame, me a mau ong komail, aramas ta men en kam kila aramas akan, pwe kainok pokon ender lokidokila.',
        51: 'A kaidik sang pein i, me a katitiki met, a i me samero lapalap ni par o, i ari kopada, me Iesus pan kamataki kainok o.',
        52: 'A kaidik kainok eta, pwe a pil pan kapokon pena seri en Kot akan, me muei pasang nin sap akan.',
        53: 'Sang ni ran o irail raparapaki en kamatala i.',
        54: 'Iesus ap solar kotikot sili sansal ren Sus oko, pwe a kotilang eu sap impan sap tan ni kanim eu ad a Epren, o kotikot ia iang sapwilim a tounpadak kan.',
        55: 'A pasa en Sus oko me korendor, o me toto koeie sang nan sap karos, kodalang Ierusalem mon pasa, pwen kamaui pein irail.',
        56: 'Irail ari raparapaki Iesus idedok nan pung arail, ni ar pokopokon nan im en kaudok: Da me komail lamelame, a sota pan ko dong kamadip o?',
        57: 'A samero lapalap o Parisär akan wiadar kusoned eu, meamen me asa wasa a kot ia, i en kasaleda, pwe ren saikidi i.',
    },
    12: {
        1: 'PONG wonu pong mon pasa Iesus kotilang Petanien, wasa Lasarus me melar, kauson ia, me Iesus kotin kamauredar sang ren me melar akan.',
        2: 'Irail ari kaonopada konot, pwe a en kotin kasipong re’rail; Marta papa, a Lasarus amen irail me iang I kotikot ni tepel.',
        3: 'Maria ap wado paun en men kei eu, udan pil en narde, me kasampwalia, keiedi ong ni aluwilu en Iesus o limwieki a pwilipeipei aluwilu a; a im o me dir kila po en men kei.',
        4: 'Iudas Iskariot, amen ren sapwilim a tounpadak kan, nain Simon, me pan pangala i, ap indada:',
        5: 'Da men kei wet sota netilar, kareda denar silepuki, ap nek ong samama kan?',
        6: 'Kaidik a pok ong me samama kan, me a idokki met, a pweki lipirap amen i, o saunkanikid en moni, wewa moni, me aramas kidar.',
        7: 'Iesus ap kotin masani: Der mokidi ong i! Pwe a kaonopadang ran en ai pan saredi.',
        8: 'Pwe me samma kan kin potopot re omail, a ngai sota sota kin potopot re omail.',
        9: 'Sus oko me toto ari asaer, me a kot wasa o, irail ari kodo pweki Iesus o pil, pwen kilang Lasarus, me a kotin kamauredar sang ren me melar akan.',
        10: 'Samero lapalap akan pil raparapaki, en pil kamela Lasarus.',
        11: 'Pwe Sus oko toto kola o poson Iesus pweki i.',
        12: 'Mandan ran o aramas toto, me toun iang kamadip o, lao rong, me Iesus pan kotilang Ierusalem,',
        13: 'Ap paledi ran tuka kan o koieila tu ong i, ngisingisida: Osiana! Meid iasanai me kotido ni mar en Kaun o Nanmarki en Israel!',
        14: 'A Iesus lao kotin masani esel pul amen, ap kaipokedi poa, duen a intingidier:',
        15: 'Der masak nain Sion seripein! Kilang om Nanmarki kotido, kaipokedi pon nain esel amen.',
        16: 'A sapwilim a tounpadak kan sota madang weweki mepukat. A Iesus lao linganlar, irail ap tamanda mepukat, me indingidier duen i, o me ir wiai ong i mepukat.',
        17: 'A pokon o, me iang i ni a kotin molipei Lasarus sang nan sousou o, ni a kotin kamauredar i sang ren me melar akan, kadede i!',
        18: 'Iei me aramas kokiieilang i, pwe irail rongadar, me a kotin wiadar kilel wet.',
        19: 'Parisär oko ap indada nan pung ar: Komail kilang, me komail sota kak wia meakot. Kilang, toun sap akan idauenla i.',
        20: 'Akai men Krik iang irail, me koda dong kamadip o, pwen kaudok.',
        21: 'Mepukat ko dong Pilipus, men Petsaida en Kaliläa, poeki re a indada: Maing, se men udial Iesus.',
        22: 'Pilipus ap kodo kaireki Andreas, a Andreas o Pilipus kaireki Iesus.',
        23: 'A Iesus kotin sapeng irail masani: Ansau leler, me Nain aramas pan kalinganla.',
        24: 'Melel, melel I indai ong komail, ma wan korn so moredi ong nan pwel o mela, a pan kelepata, a ma a pan mela, a pan kaparapar wa toto.',
        25: 'Me pokepoke maur i, pan salongala; a me tounmeteki maur i pali pa, pan diarada maur soutuk.',
        26: 'Meamen papa ia, i en idauen ia! A wasa I mi ia, i wasa me papa ia, pan pil mi ia. Ma meamen papa ia, i me Sam o pan kasapwilada.',
        27: 'I ap lol olar, a da me I en inda? Sam kamaio wei sang ia ansau wet, ari so, i me I koki dong ansau wet.',
        28: 'Sam, kalinganada mar omui! Ngil eu ap peidido sang nanlang indada: I kalinganadaer, o I pan pil kalinganada.',
        29: 'A aramas akan me u sili me rongadar, indada: A nansapwe. A akai indada: Tounlang amen me kasoia ong i.',
        30: 'Iesus kotin sapeng masani: Kaidik pweki ngai, me ngil wet wiauikier a pweki komail.',
        31: 'Met ansau en kadeik en sappa wet. Met kaun en sappa et pan lokidokila.',
        32: 'A ngai lao langada sang sappa, I pan kainonga dong ia karos.',
        33: 'I me a kotin kokop kidar duen a pan kamatala.',
        34: 'Aramas akan sapeng i: Se rongadar sang nan kapung o, me Kristus pan potopoteta, a iaduen, kom kasoiada, me Nain aramas en kakauda. Is Nain aramas men et?',
        35: 'Iesus ap kotin masani ong irail: Marain mi re omail ansau kis. Weweid, ni ansau marain mi re omail, pwe rotorot ender kono komail edi. Pwe me kin weweid nan rotorot, kin sasa wasa, me a ko ong ia.',
        36: 'Poson marain, ni a mimi re omail, pwe komail en seri en marainla. Iesus kotin masani mepukat, ap kotila karukila pein i sang irail.',
        37: 'A i me kotin wiadar kilel toto mo’rail, ari so, irail sota poson i,',
        38: 'Pwe kokop en saukop Iesaia en pwaida, me a masani: Kaun o, is me poson at kasoi? O is me lim en Kaun kasansal ong?',
        39: 'Irail ari sota kak poson, pwe Iesaia pil katitiki:',
        40: 'A kotin karotongala mas arail o kakekaluakala mongiong arail, pwe ren so kilangki mas arail, o asaki mongiong arail, o wukila, o I en kakel ir ada.',
        41: 'Mepukat Iesaia masanier, ni a kilanger a lingan o katitiki i.',
        42: 'Ari ren saumas lapalap me toto, me poson i, a pweki Parisär akan re sota ponasa i, pwe ren der lokidokila sang nan sinakoke.',
        43: 'Pwe re mauki konekon ren aramas akan mon konekon ren Kot.',
        44: 'Iesus kotin kapitie laudeda masani: Me poson ia, kaidin ngai, me a kin poson, a me kadar ia dor.',
        45: 'A me kilang ia, a pil kilang, me kadar ia dor.',
        46: 'I kodon kamaraini sappa, pwe amen amen me poson ia, ender mimieta nan rotorot.',
        47: 'A ma meamen rong ai padak kan, ap sota apapwali, I sota kin kadeikada i, pwe I sota kodon kadeikada sappa, a pwen kamaurida sappa.',
        48: 'Me kase ia la o so oke ai padak kan, nan kadeikapa mia: Ai padak, me I kida, i me pan kadeikada i ni ran nik o.',
        49: 'Pwe I sota padaki wei sang pein ngai. A Sam, me kadar ia dor, i me ki ong ia er kusoned eu, me I en inda o padakieki.',
        50: 'O I asa, maur soutuk a kusoned o. Ari, karos me I padaki wei, I kin padaki duen Sam masani ong ia.',
    },
    13: {
        1: 'MON kamadip en pasa Iesus lao kotin mangier, me ansaun a pan kotila sang sappa, kotila ren Sam a korendor, duen a kotin kupuramauki sapwilim a kan, me mi sappa, iduen a kotin kupura irail lel imwi,',
        2: 'Ni ar kotin kasipong ansau me tewil ki ong er nan mongiong en Iudas Iskariot nain Simon, en pangala i.',
        3: 'Iesus lao kotin mangier, me Sam kotiki onger ni lim a kan meakaros, o me a kotido sang ren Kot, o me a pan kotila ren Kot,',
        4: 'Ap kotida sang ni kasipong, kotikidi sapwilim a likau en liki ap ale dauel eu pirakidi pein i,',
        5: 'A wutoki pil nan dal, ap pikikidi widen nä en sapwilim a tounpadak kan, o limwieki dauel, me a piraki pena.',
        6: 'A lao kotin lel Simon Petrus, a ap potoan ong i: Maing, re pan kotin widen nä i kat?',
        7: 'Iesus kotin sapeng masani ong i: Koe kin sasa, me I wia metet, a mur koe pan asala.',
        8: 'Petrus potoan ong i: Re sota pan kotin widen nä i kat kokolata. Iesus kotin sapeng i: Ma I sota widen uk, nan sota pwais om re i.',
        9: 'Simon Petrus ap potoan ong i: Maing, kaidin nä eta, a pil pa o mong ai!',
        10: 'Iesus kotin masani ong i: Me duduer, solar mau ong omiom o opinok, pwe a makelekeler, a nä eta, me pan wideut; komail me makelekel, a kaidin karos.',
        11: 'Pwe a kotin mangi, me pan pangala i; i me a kotin masanieki: Kaidin komail karos me makelelkel.',
        12: 'A lao kotin widener nä ar akan, a kotin pur ong sapwilim a likau en liki. A pil kaipokedi ni tepel masani ong irail: Komail asaer me I wiai ong komail er?',
        13: 'Komail kin adane kin ia Saunpadak o Kaun, ari me pung, pwe iei ngai.',
        14: 'Ari, ma ngai, Kaun o Saunpadak widen nä omail, komail ari pil widen nä omail pena.',
        15: 'Pwe I ki ong komail er sansal mau eu, pwe komail en kaalemongi ia, o wia, duen I wiai ong komail.',
        16: 'Melel, melel I indai ong komail, ladu me sota laude sang a saumas, de me pakadarado me sota laude sang me kadarado i.',
        17: 'Ma komail asa mepukat, komail meid pai, ma komail wiada.',
        18: 'Kaidin komail karos, me I indinda. I asa, me I piladar. A pwe kisin likau en pwaida: Me iang ia kangkang prot, kin tiaki ia di.',
        19: 'Ansau wet I indai ong komail mepukat mon a pan wiaui, pwe a lao wiaui, komail en poson, me ngai i.',
        20: 'Melel, melel I indai ong komail, meamen me kasamo, me I kadar wei, kin kasamo ia, a me kin kasamo ia, kin kasamo, me kadar ia do.',
        21: 'Iesus lao kotin masani wei mepukat, ap kupurola kadede masani: Melel, melel I indai ong komail, amen komail pan pang ia la.',
        22: 'Sapwilim a tounpadak kan ap soupei pena o sasa, is i, me a kotin masanieki.',
        23: 'A amen sapwilim a tounpadak kan, me Iesus kotin kupura mauki, momod ni tepel impan Iesus.',
        24: 'Simon Petrus ap olol ong i, en idok, is i me a kotin masani.',
        25: 'I ap kai ong pan kupur en Iesus potoan ong i: Maing, is i?',
        26: 'Iesus kotin sapeng: Iei i, me I pan ki ong kisin prot i lao kaduedier nan dal o. A lao kotin kaduedier kisin prot o, a kotiki ong Iudas Iskariot nain Simon.',
        27: 'A lao tungole kisin prot o, Satan ap tilong lole. Iesus ap kotin masani ong i: Wiada madang, me koe pan wiada!',
        28: 'A sota, ren me momod ni tepel, asa, da me a kotin masanieki ong i met.',
        29: 'Pwe akai kiki ong, me Iesus kotin masani ong i: Netie dong kitail kapwa en kamadip o, de a en ki ong me samama ko meakot, pwe a kin wewa ed en moni.',
        30: 'A lao tungoler kisin prot, ap madang pedoi wei, a wasa pongier.',
        31: 'A lao pedoi sanger, Iesus ap kotin masani: Nain aramas ari linganlar, o Kot me lingana kilar i.',
        32: 'Ma Kot lingan kilar i, Kot ap pan pil kalinganaki pein i. A pan madang kalinganada i.',
        33: 'Seri ko, I pan ieiang komail ansau kis, komail pan rapa kin ia, a duen I indai ong Sus akan: Wasa me I pan kola ia, komail sota pan kak ong. Iei duen I pil indai ong komail ansau wet.',
        34: 'I ki ong komail kusoned kap eu, pwe komail en poke pena, duen I pok ong komail er, iei duen komail en poke pena!',
        35: 'Pwe i me karos pan asaki, me komail ai tounpadak kan, ma komail limpok pena.',
        36: 'Simon Petrus potoan ong i: Maing, re pan kotila ia? Iesus kotin sapeng i: Wasa me I pan kola ia, koe sota kak idauen ia ansau wet, a koe pan idauen ia eu ran.',
        37: 'Petrus potoan ong i: Maing, da me i so kak idauen ir ki met? I pan kasela maur i pweki komui.',
        38: 'Iesus kotin masani ong i: Koe pan kasela maur om pweki ngai? Melel, melel I indai ong uk, mon malek pan kakorot, koe pan kamam kin ia pan me sili pak.',
    },
    14: {
        1: 'MONGIONG omail der padau! Komail kin poson Kot; en pil poson ia!',
        2: 'Nan tanpas en Sam ai pera toto mia. Ma so I pan indai ong komail. Pwe I kokolan kaonopada deu’mail,',
        3: 'Ma I kola kaonopada deu’mail, I pan puredo, uk komail dong ia. Pwe wasa I kin mi ia, komail en pil mi ia.',
        4: 'A komail asa, wasa I kola ia, o komail asa al o.',
        5: 'Tomas potoan ong i: Maing, se sasa, wasa re pan kotila ia, o pala se pan asa al o?',
        6: 'Iesus kotin masani ong i: Ngai me al, o melel, o maur, sota me kak kodong Sam, ma so ngai.',
        7: 'Ma komail asa ia er, komail pil asa Sam ai. A komail asa i sang ansau wet kokolata o kilangadar i.',
        8: 'Pilipus potoan ong i: Maing, kotin kasale dong kit Sam, kit ap pan nenenla!',
        9: 'Iesus kotin masani ong i: Pilipus, I ieiang komail er ansau warai, a koe so wewe kin ia? Me kilang ia er i me kilangadar Sam. A iaduen om indada: Kasale ong kit Sam?',
        10: 'Koe so kamelele, me ngai podidi ong Sam o Sam podidi ong ia? A padak kan, me I ki ong komail, kaidin pein ai, a en Sam, me mi re i, i me kin wiawia dodok pukat.',
        11: 'Kamelele ia, ngai podidi ong Sam, o Sam kin podidi ong ia; a ma so, komail kamelele ia pweki ai wiawia kan.',
        12: 'Melel, melel I indai ong komail, meamen poson ia, a pil pan wiawia dodok kan me I kin wiawia, o a pan wiada, me lapa sang mepukat, pweki I kokola ren Sam.',
        13: 'A meakot komail pan poeki ni ad ai, iei me I pan wia, pwe Sam en lingana kida Na.',
        14: 'Ma komail pan poeki maekot ni ad ai, I pan wia.',
        15: 'Ma komail pok ong ia, en kapwaiada ai kusoned akan!',
        16: 'A I pan poeki ren Sam, a i me pan porone dong komail amen saunkamait, pwen mi re omail kokolata.',
        17: 'Ngen en melel, me sappa so kak ale, pwe re sota kilang i pil sota asa i. A komail asa i pwe a kin mi re omail, o a pan mi lol omail.',
        18: 'I sota pan mueid ong komail, en sapoupou, I pan ko dong komail.',
        19: 'Ansau kis sappa solar pan kilang ia, a komail kin kilang ia. Ngai me maur, o i me komail pil pan memaureki.',
        20: 'Ni ran o komail pan asa, me ngai podidi ong Sam ai o komail podidi ong ia o ngai ong komail.',
        21: 'Me aleer ai kusoned akan o kapwaiada, iei me kin pok ong ia, a me kin pok ong ia, kin konekon ren Sam ai, a I pan pok ong i, o kasansale ong i pein ngai.',
        22: 'Iudas, kaidik Iskariot, potoan ong i: Maing, iaduen re pan kotin kasansale ong kit pein ir, a ong sappa so?',
        23: 'Iesus kotin sapeng masani ong i: Ma meamen pok ong ia, a pan kapwaiada ai padak kan, a Sam ai pan pok ong i, a se pan ko ong re a kaukauson re a.',
        24: 'A me so pok ong ia, sota kin kapwaiada ai padak kan. A kaidik ai padak, me komail kin rong, a en Sam o, me kadar ia dor.',
        25: 'Mepukat I padaki ong komail er ni ai mi re omail.',
        26: 'A saunkamait, Ngen saraui, me Sam o pan poronedo ni ad ai, i me pan kawewe ong komail meakaros o kataman kin komail me I padaki ong komail er.',
        27: 'I mueid ong komail popol. Ai popol me I ki ong komail, kaidin duen sappa kikida, me I ki ong komail. Mongiong omail der patau, pil der masak.',
        28: 'Komail rongadar, me I indai ong komail er, I koko wei o pan pure dong komail. Ma komail pok ong ia, komail pan perenki, me I kokola ren Sam, pwe Sam o me lapa sang ia.',
        29: 'Ansau wet I indai ong komail er mepukat, mon a pan wiaui, pwe a lao wiaui, komail en poson.',
        30: 'I solar pan kasokasoi toto ong komail, pwe kaun en sappa o kokodo, a sota a meakot re i.',
        31: 'A pwe sappa en asa, me I kin pok ong Sam, o me I kin wiawia duen me Sam masani ong ia er, kitail en uda kokowei!',
    },
    15: {
        1: 'NGAI wain melel pot, a Sam ai saumat.',
        2: 'Ra karos, me podidi ong ia, ap sota wa, a kin lepuke sang, a karos me wa, a kin koko, pwen wa totola.',
        3: 'Komail ari makelekel kidar padak, me I ki ong komail er.',
        4: 'Komail podidi ong ia o ngai ong komail. Ra sota kak pein wa, ma a so podidi ong wain, iduen komail, ma komail so podidi ong ia.',
        5: 'Ngai wain pot, a ra kan komail. Me podidi ong ia o ngai ong i, iei i, me kin wawa toto; pwe komail sota kak wia meakot ma sota ngai.',
        6: 'Meamen so podidi ong ia, pan lokidokila dueta ra, ap mongedi; aramas kin wasa ir pena, kase ir ala nani iai, ir ari pan rongala.',
        7: 'Ma komail podidi ong ia, o ai padak kan podidi ong komail, komail pan poeki meakot, me komail mauki, a a pan pwai ong komail.',
        8: 'Nan i me Sam ai kalingana kila, omail wawa toto, o komail pan wiala ai tounpadak kan.',
        9: 'Due Sam o pok ong ia er, iduen I pil pok ong komail; komail podidi ong ai limpok!',
        10: 'Ma komail pan peiki ong ai kusoned akan, komail pan podidi ong ai limpok, duen I kin peiki ong en Sam ai kusoned akan, o podidi ong a limpok.',
        11: 'Mepukat I padaki ong komail er, pwe ai peren en podidi ong komail, o omail peren en unsokela.',
        12: 'Nan iet ai kusoned: Komail en poke pena, duen i pok ong komail er.',
        13: 'Sota me a limpok laude sang met, me pan mueid kila maur i kompokepa kan.',
        14: 'Komail me kompokepa i, ma komail wiawia, me I indai ong komail.',
        15: 'I solar kaadaneki komail ladu, pwe ladu sasa, me a saumas kin wia. A I kaadane kin komail kompokepa i kan, aki I kasale ong komail er karos, me I rongadar sang ren Sam ai.',
        16: 'Kaidin komail me pil ia dar, a ngai me piladar komail o kilele ong komail, en kokowei kapareda wa, o omail wa en mimieta, pwe karos, me komail pan poeki ren Sam ni ad ai, a pan kotiki ong komail.',
        17: 'A iet me I panaui kin komail, komail en poke pena!',
        18: 'Ma sappa kailong kin komail, komail en asa, me a kailong kin ia mo omail.',
        19: 'Ma kisan sappa komail, sappa pan pok ong me a; a komail kaidin kisan sappa, pwe I pil komail dar sang sappa, iei me sappa kailong kin komail.',
        20: 'Tamatamanda kasoi o, me I kasoia ong komail er: Ladu me sota laude sang a saumas ma re kame ia er, re pil pan kame komail. A ma irail pan kapwaiada ai padak, re pil pan kapwaiada omail.',
        21: 'A mepukat karos re pan wiai ong komail pweki ad ai, aki ar so asa me kadar ia dor.',
        22: 'Ma I so kodo o padaki ong irail, nan sota pan dip arail, a met sota peikid pan dip arail.',
        23: 'Me kailong kin ia, pil kin kailongki Sam ai.',
        24: 'Ma I so wiadar dodok kan nan pung arail, me sota amen wiadar, nan sota pan dip arail. A met irail kilanger o kailong kin ia er o pil Sam ai.',
        25: 'A mepukat wiauier pwe masan o en pwaida, me intingidier nan arail kapung: Irail kailong kin ia, a sota karepa.',
        26: 'A saunkamait lao kodoer, me I pan kadarado sang ren Sam, iei Ngen en melel, me kin kodo sang ren Sam, i me pan kadede ngai.',
        27: 'A komail pil pan kadede, pwe komail iang ia er sang ni tapi o.',
    },
    16: {
        1: 'MEPUKAT I padaki ong komail er pwe komail der makarada.',
        2: 'Irail pan kase komail la sang nan sinakoke, a eu ansau kokodo, meamen kame komail la, pan kiki ong, me a papa Kot.',
        3: 'A mepukat re pan wiai ong komail, pweki ar sasa Sam o ngai.',
        4: 'A mepukat I padaki ong komail er, pwe ansau lao leler, komail en tamanda, me I indai ong komail er. A mepukat I sota indai ong komail er ni tapi o, pwe I ieiang komail.',
        5: 'A met I kola ren me kadar ia do, a sota amen komail kin idok re i: Ia wasa kom pan kola ia?',
        6: 'A pweki ai padaki ong komail mepukat, mongiong omail me dir en insensued.',
        7: 'Ari so, I kasoi ong komail melel, me mau ong komail I en kola. Pwe ma I so kola saunkamait sota pan pwara dong komail. A ma I kola, I pan kadara dong komail i.',
        8: 'A i lao kodo, a pan kasaui ong sappa dip, o pung, o kadeik.',
        9: 'Duen dip, pweki irail sota poson ia.',
        10: 'Duen pung, pweki I kola ren Sam, o komail solar pan kilang ia.',
        11: 'A duen kadeik o, pweki kaun en sappa wet me pakadeikadar.',
        12: 'I men padaki ong komail me toto, a met komail sota kak ong.',
        13: 'A Ngen en melel lao pwarado, a pan padaki ong komail melel akan karos. Pwe a sota pan padaki wei sang nan pein i, a meakot a pan rong, i me a pan indada. O a pan kasale ong komail meakan me pan wiaui.',
        14: 'A pan kalingana ia da, pwe a pan ale me ai o kasale ong komail.',
        15: 'Sapwilim en Sam meakaros, iei me pil udan ai. I me I indakier, me a pan ale me ai o kasale ong komail.',
        16: 'Murin ansau kis komail solar pan kilang ia; o pil murin ansau kis, a komail pan kilang ia, pwe I kola ren Sam.',
        17: 'Sapwilim a tounpadak kai ap indada nan pung ar: Dakot met, me a kotin masani ong kitail: Murin ansau kis komail solar pan kilang ia, o pil murin ansau kis, a komail pan kilang ia, pwe I kokola ren Sam?',
        18: 'Irail ap indada: Dakot murin ansau kis, me a kotin masanieki? Kitail sota weweki, me a kotin masani.',
        19: 'A Iesus kotin angi, me re men idok re a, ap kotin masani ong irail: Komail kakaaki nan pung omail, me I indada: Murin ansau kis komail solar pan kilang ia, o pil murin ansau kis, a komail pan kilang ia.',
        20: 'Melel, melel I indai ong komail, komail pan sangesang o mamaiei, a sappa pan pereperen; komail pan mamauk, a omail mauk pan wiki ong popol.',
        21: 'Li o ni a pan naitik kin insensued, aki a ansau leler; a a lao naitikidier seri o, a solar kin tamanda a insensued, aki a peren kida, me aramas amen ipwidi ong sappa.',
        22: 'Pil dueta komail kin insensued ansau wet. A I pil pan kilang komail o mongiong omail pan pereperen. A sota me pan atia sang komail omail peren.',
        23: 'A lao ni ran o komail sota pan idok re i meakot. Melel, melel I indai ong komail, ma komail pan poeki meakot ren Sam ni ad ai, a pan kotiki ong komail.',
        24: 'Sang mas kokodo komail sota poeki meakot ni ad ai. Poeki, a komail pan ale; pwe omail peren en unsokela.',
        25: 'Mepukat I padaki ong komail er ni karaseras akan. A eu ansau kokodo, me I solar pan padapadak ni karaseras, pwe I pan sansal padaki ong komail duen Sam.',
        26: 'Lao ran o komail pan poeki ni ad ai. A I sota indai ong komail, me I pan kapakapa kin komail ren Sam.',
        27: 'Pwe Sam pein pok ong komail, pweki komail pok ong ia er o kamelele, me I kodo sang ren Kot.',
        28: 'I kodo sang ren Sam o kodido sappa; I pil kokola sang nin sappa, kokola ren Sam.',
        29: 'Sapwilim a tounpadak kan potoan ong i: Masani, ansau wet re kin kotin sansal padaki ong kit o solar ni karaseras.',
        30: 'Kit ap asaer, me re kotin mangier meakaros, o re sota mau ong, amen en idok meakot re omui. I me se posonki, me re kotido sang ren Kot.',
        31: 'Iesus kotin sapeng irail: Komail posonlar met?',
        32: 'Kilang, ansau kokodo, ari a leler, me komail pan kamueit pasang, amen amen nan udan deu a o kase ia la. I ap pan kelep; ari so, I sota kin kelep, pwe Sam o ieiang ia.',
        33: 'Mepukat I padaki ong komail, pwe komail en popole kin ia. Nan sappa komail kin kalokolok, ari so, komail popol, pwe I kaloedier sappa.',
    },
    17: {
        1: 'IESUS kotin masani wei mepukat, ap kotin masanda nanlang masani: Sam ai, ansau o leler, en kalinganada sapwilim omui Ol, pwe sapwilim omui Ol en pil kalinganada komui.',
        2: 'Duen komui kotiki ong i er manaman, en poedi uduk karos, pwe a en ki ong karos, me komui ki ong i er, maur soutuk.',
        3: 'A iet maur soutuk: Ren asa komui la, me komui ta Kot melel, o Iesus Kristus, me komui kadarador.',
        4: 'I kalingana komui dar nin sappa, I kanikialar dodok, me komui kotiki dong ia, I en wiada.',
        5: 'A met Sam ai, kom kotin kalingana kin ia pein omui lingan, me I linganakier, ni ai mi re omui, ni sappa saikenta mia.',
        6: 'I kasansale ong aramas akan mar omui, me komui ki ong ia er sang nin sappa. Irail udan noumui, a komui ki ong ia er irail; a re kin kapwaiada omui masan.',
        7: 'A met re asalar, me karos, me komui ki ong ia er, pwili sang komui.',
        8: 'A masan akan, me komui ki ong ia er, i me I ki ong irail er, o irail aleer o wewekilar melel, me I pwarado sang komui, o re posonlar, me komui kadar ia dor.',
        9: 'I kin kapakapa kin ir, I sota kin kapakapa kin sappa, a irail, me komui ki ong ia er, pwe noumui irail.',
        10: 'Pwe karos me ai, iei noumui; a karos me noumui, iei ai o I lingan kin irail lar.',
        11: 'I solar mi sappa, a mepukat mi sappa. I kola re omui. Sam ai saraui, kanikid irail ni mar omui, me komui ki ong ia er, pwe irail en me ta men dueta kita.',
        12: 'Ni ai mi re irail, I nikid irail er ni mar omui, me komui ki ong ia er; I nikid irail er; sota amen ir salongalar, seri salongala eta, pwe kisin likau en pwaida.',
        13: 'A met I koko wei re omui. I padaki wei mepukat nan sappa, pwe ai peren unsok en mi re’rail.',
        14: 'I ki ong irail er omui masan, o sappa kailong kin irail er, pwe irail kaidin kisan sappa, dueta, ngai kaidin kisan sappa.',
        15: 'I sota kin poeki, komui en wa irail sang nin sappa, a pwe komui en pera wei sang irail me sued.',
        16: 'Irail kaidin kisan sappa, dueta ngai kaidin kisan sappa.',
        17: 'Kasaraui kin ir ala melel, pwe me melel omui masan.',
        18: 'Duen komui kadar ia dong sappa, iduen I kadar ir alang sappa.',
        19: 'I kasarauila pein ngai pweki irail, pwe irail kasaraui kila melel.',
        20: 'A kaidin mepukat eta, me I kapakapaki, a pil irail, me pan poson ia pweki arail padak.',
        21: 'Pwe irail karos en me ta men, duen komui Sam podidi ong ia o ngai ong komui, pwe irail en pil me ta men re ata, pwe sappa en poson, me komui kadar ia dor.',
        22: 'A lingan, me komui ki ong ia er, I ki ong irail er, pwe irail en me ta men, dueta kita me ta men.',
        23: 'Ngai ong irail, o komui ong ia, pwe re en song laieu, pwe sappa en asa, me komui kadar ia dor, o pok ong irail, dueta komui pok ong ia er.',
        24: 'Sam, I men, irail, me komui ki ong ia er, en pil mi wasa, me I kin mi ia, pwe ren ududial ai lingan, me komui ki ong ia er, pwe komui pok ong ia er mon sappa a tapidar.',
        25: 'Sam ai pung, sappa sasa komui, a ngai me asa komui, a mepukat asaer, me komui kadar ia dor.',
        26: 'O I kasale ong irail er mar omui. O I pan pil kasaleda i, pwe limpok ota, me komui poke kin ia er, en podidi ong ir o ngai ong irail.',
    },
    18: {
        1: 'IESUS lao kotin masanier mepukat, ap kotila palilan pil Kidron, o sapwilim a tounpadak kan iang i: Matuel eu mi wasa o, me i o sapwilim a tounpadak kan kotilong ong lole.',
        2: 'A Iudas me pangala i, pil asa wasa o, pwe Iesus o sapwilim a tounpadak kan kin purepure wasa o.',
        3: 'Iudas lao aleer pokon o papa kan sang ren samero lapalap o Parisär akan, ap kokiieila lamp, o ser akan, o kapwa en pei kan.',
        4: 'A Iesus me kotin mangier meakaros, me pan pit i, kotiei wong irail masani ong irail: Is me komail rapaki?',
        5: 'Re sapeng i: Iesus men Nasaret. Iesus kotin masani ong irail: Ngai i. A Iudas, me pangala i, pil u iang irail.',
        6: 'Iesus lao kotin masani ong irail: Ngai i, re ap puioki sang, pupodi ong nan pwel.',
        7: 'A pil kotin kainoma re irail. Is me komail rapaki? Irail inda: Iesus men Nasaret.',
        8: 'Iesus kotin masani: I indai ong komail er, me ngai i. Ari, ma komail rapakin ia, en purewei sang mepukat!',
        9: 'Pwe lepen masan en pwaida, me a kotin masanier: Sota amen irail, me komui ki ong ia er, me salongalar.',
        10: 'A Simon Petrus, me na kodlas mia, ap usa pasang, päleki en samero lapalap a ladu, päle pasang salong a pali maun. A ladu o me ad a Malkus.',
        11: 'Iesus ap kotin masani ong Petrus: Kapure ong om kodlas nan deu a! Da, dal o, me Sam o kotiki ong ia er, i ender nim?',
        12: 'Ari, pokon o, o ar kaun, o papa en men Sus akan saikidi Iesus o saliedi i.',
        13: 'O kalua mas ren Anas, pwe i sam en Kaipas a paud o samero lapalap ni par o.',
        14: 'Iei i Kaipas, me indai ong Sus oko: Me mau, aramas ta men en kam kila aramas akan.',
        15: 'A Simon Petrus o pil amen tounpadak idauenla Iesus. A tounpadak men et, me samero lapalap asaer, iang Iesus kotilong ong nan matuel en samero lapalap.',
        16: 'A Petrus u liki impan wanim o. Tounpadak teio, me samero lapalap asaer, pedoi sang kasokasoi ong me sinsila wanim o ukelong ong Petrus lole.',
        17: 'Seripein o, me sinsila wanim, ap indai ong Petrus: Kaidin amen ren tounpadak kan en aramas men et koe? A inda: Ngai so.',
        18: 'A ladu o papa kan u wasa o, saunda kisiniai, pwe a kapau; irail rangerang ia, a Petrus pil iang u rangerang.',
        19: 'Samero lalalap ap kalelapok ren Iesus duen sapwilim a tounpadak kan o duen a padak.',
        20: 'Iesus kotin sapeng i: I padapadak sansal ong sappa; ansau karos I kaukawewedar nan sinakoke o nan im en kaudok, wasa me Sus oko karos kin pokon pena ia; a sota man meakot, me I padak wasa rir.',
        21: 'Da me kom peidokki re i? Kalelapok ren me rong ia er, me I padaki ong irail er, kilang, re asa, me I indada.',
        22: 'Ni en Iesus a kotin masani met, amen sang ren papa ko, me uda impa, ap pikir silang en Iesus indada: Iduen om sapeng ong samero lapalap?',
        23: 'Iesus kotin sapeng i: Ma ai lokaia sued, koe ap kadede ki duen a sued, a ma me pung menda koe pikir ia?',
        24: 'A Anas ap kadar wong sensal ren samero lapalap Kaipas.',
        25: 'A Simon Petrus u, rangerang irail ap indai ong i: Ele koe pil amen a tounpadak kan? A kamamada indada: Ngai so.',
        26: 'Ladun samero lapalap amen, me sauneki ol o, me Petrus pale sang salong a, ap indada: Kaidin koe me i kilanger re a nan matuel o?',
        27: 'Petrus ap pil kamamada. Malek madang kakorotada,',
        28: 'Irail ap kalua sang Iesus ren Kaipas, walang nan im en kadeik. Ari, me sangkonai. A irail sota pedelong ong nan im en kadeik, pwe re de kasaminela pein irail, pwe re en kak ong tungole pasa.',
        29: 'Pilatus ap pedoi wong re irail indada: Da me komail karauneki aramas men et?',
        30: 'Irail sapeng indang i: Ma men et sota me sued amen, se sota pan pangalang komui i.',
        31: 'Pilatus ap masani ong irail: Pein komail ale i, kadeikada i duen omail kapung. Sus oko ap indai ong i: A sota muei ong kit, sen kamela amen.',
        32: 'Pwe masan en Iesus en pwaida, me a kotin masanieda, pwen kasaleda, duen a pan kamatala.',
        33: 'A Pilatus pur ong nan im en kadeik ekeredo Iesus, kalelapok re a: Komui Nanmarki en Sus akan?',
        34: 'Iesus kotin sapeng i: Kom indada mepukat sang nan pein omui pam? De akai indai ong komui duen ngai?',
        35: 'Pilatus sapeng: Da, men Sus amen ngai? Toun sap omui o samero lapalap akan panga dong ia komui; da me komui wiadar?',
        36: 'Iesus kotin sapeng: Ai wei kaidin men sappa et. Ma ai wei men sappa et, nan ai papa kan pan pepeita, pwe I ender pan pangalang Sus akan; a kaidin ai wei ansau wet,',
        37: 'Pilatus ap indai ong i: Ari, Nanmarki amen komui? Iesus kotin sapeng: Komui me inda, me Nanmarki amen ngai. I me I ipwikidier o pwara kidong sappa pwe I en kadede melel. Kisan melel akan kin rongerong ngil ai.',
        38: 'Pilatus indai ong i: Dakot melel? A lao indawei mepukat, ap pil pedoi ong ren men Sus indai ong irail: I sota man diar dip a.',
        39: 'A tiak eu mi re omail, i en lapwada meamen ni pasa. Komail so men, i en lapwadang komail Nanmarki en Sus akan?',
        40: 'Irail karos pil weriwereda indada: Kaidik men et, a Parapas! A Parapas me lolap amen.',
    },
    19: {
        1: 'PILATUS ap ale Iesus wokida i.',
        2: 'A saunpei ko irada el en tek eu, rap kidang pon kadokenmai o kapwataki i likau waitata.',
        3: 'Re ap kai dong i indada: Iong Nanmarki en Sus akan! O re pikir silang i.',
        4: 'Pilatus ap pil pedoi indai ong irail: Kilang, i wa dong komail i, pwe komail en asa, me i sota diaradar dip a.',
        5: 'Iesus ap kotieila, kapwataki el en tek o likau pup waitata. A indai ong irail: Kilang, song en aramas o!',
        6: 'Samero lapalap o papa ko lao udial i, irail ap weriwereda indada: Kalopuela i! Kalopuela i! Pilatus indai ong irail: Pein komail ale i kalopuela i! Pwe i sota diar dip a.',
        7: 'Sus oko sapeng i: At kapung mia, a duen at kapung a pan kamatala, pwe a wiaki sapwilim en Kot pein i.',
        8: 'Pilatus lao rongadar mepukat, ap masapwekadar kaualap,',
        9: 'O purelong ong nan im en kadeik o, kalelapok ren Iesus: Komui koti sang ia? A Iesus sota kotin sapeng i.',
        10: 'Pilatus ap indai ong i: Komui sota sapeng ia? Komui sota asa, me i manaman ong kapiti uk ala o pil manaman ong kalopue uk ala?',
        11: 'Iesus kotin sapeng: Sota man om manaman en kaoe ia, ma a so muei ong komui sang poa. Ari, dip en me panga ia dong komui er me lapa sang.',
        12: 'Ari, Pilatus ap song kapitila i, a Sus oko weriwer indada: Komui kaidin kompoke pan Sisa, ma komui pan kapitila men et. Meamen kasapwiladang nanmarki pein i kin palian Sisa.',
        13: 'Pilatus lao rongadar kasoi pukat ap kapwareda Iesus, kaipokedi pon deun kadeik, wasa me adaneki Pepment, a ni lokaia en Ipru: Kapata,',
        14: 'A i ran en onop ong pasa impan auer kawonu. I ari masani ong Sus oko: Kilang, omail Nanmarki!',
        15: 'A re weriwereda: Sikenewei! Sikenewei! Kalopuela i! Pilatus masani ong irail: Da, i en kamela omail Nanmarki? Samero lapalap akan sapeng: Sota at nanmarki, Sisa eta.',
        16: 'I ari pangalang irail i, pwen lopuela. Rap koledi Iesus kaluala.',
        17: 'A pein i kotin wa a lopu, kotilang wasa me adaneki wasan pondal, a ni lokaia en Ipru: Kolkata,',
        18: 'Wasa re kalopuela i iangaki riamen, amen ni pali maun, a amen ni pali maing, a Iesus nan pung ara.',
        19: 'Pilatus ap pil wiadar inting eu, kakonei ong pon lopu o. A iet inting: Iesus en Nasaret, Nanmarki en Sus akan.',
        20: 'Sus akan me toto, me wadokedi inting wet, pwe wasa Iesus kotin lopuela ia, me salong kanim o. A inting o wiauier ni lokaia en Ipru o Krik o Latain.',
        21: 'Ari, samero lapalap oko potoan ong Pilatus: Der intingiedi: Nanmarki en Sus akan, a me a indada: Ngai Nanmarki en Sus akan!',
        22: 'Pilatus sapeng: Me i intingiedier, i eta ai inting.',
        23: 'Saunpei ko lao kalopuela Iesus, rap ale sapwilim a likau kan, lepuk pasang, wiakida pakis paieu, pakis eu ong amen amen en saunpei ko o pil sapwilim a sakit, me so deidei pena, a pon ta sang poa lel pa.',
        24: 'Irail ap kasoi nan pung arail: Kitail ender ter pasang i, a kadoropwaki, me pan aneki, pwe kisin likau en pungala, me indinda: Irail nek pasang ai likau kan nan pung ar o kadoropwa ai sakit. Iei me saunpei ko wiakida mepukat.',
        25: 'A in en Iesus u ni tapin lopu en Iesus, o ri en in a Maria, en Kleopas a paud, o Maria men Makdala.',
        26: 'Iesus lao kotin masani in a o tounpadak men u imp a me a kotin kupura mauki, ap kotin masani ong in a: Li, kilang noum ol!',
        27: 'Ap kotin masani ong tounpadak o: Kilang in om! Ari, sang ni auer ota tounpadak o apwali i.',
        28: 'Iesus lao kotin mangier, me meakaros nikier, ap kotin masanier: I men nim pilada, pwe kisin likau en pungala.',
        29: 'A kasak mi wasa o, me audeki pineka. Irail kaduedi lim eu nan pineka, ki ong ni alek apot, kidalang ni silang i.',
        30: 'Iesus lao kotin uraker pineka, ap kotin masani: A nikier. I ari kotin kamotauiedi kadokenmai, kadarala ngen e.',
        31: 'Sus oko ap poeki ren Pilatus, me nä arail en katipitip pasang o ren wisiki sang, pwe war arail ender langelang nin lopu ran en sapat. Pwe iei ran o ran en kaonop, pwe iei ran en sapat o me lapalap.',
        32: 'Saunpei ko ap kai ong, katip pasang nä en me pali et o en me teio, me iang lopuelar.',
        33: 'A re lao kai ong Iesus o diaradar, me a matalar, rap sota katip pasang aluwilu a kan.',
        34: 'A saunpei men dokoki katieu pot pangepang a; madang nta o pil kusekusewei.',
        35: 'A me udial mepukat, kin kadede o a kadede me melel, o a asa, me a kin kadede, iei me melel, pwe komail en pil poson.',
        36: 'Pwe mepukat wiauier, pwe kisin likau en pungala: Aluwilu a sota pan tip pasang.',
        37: 'O pil eu kisin likau kin inda: Irail pan kangkakil i, me re dokodi.',
        38: 'Murin mepukat Iosep men Arimatia, tounpadak en Iesus amen, ari me rir, pweki a masak Sus oko, ap poeki ren Pilatus, en mueid ong i kalep en Iesus. Pilatus ari mueid ong i. I ari waiki sang kalep en Iesus.',
        39: 'Nikodemus me poto dong Iesus ni pong, pil kodo, wado paun epuki en potik en mire o alos.',
        40: 'Irail ap ale kalep en Iesus, kidimki pena likau linen kai iangaki pomau kan, duen tiak en Sus akan, ni ar kin sarepedi.',
        41: 'A wasa me a kotin lopuela ia, matuel eu mia ia, a nan matuel sousou kap eu mia, me saikenta amen saredi ia.',
        42: 'I wasa me ira nekidala Iesus, pweki ran en kaonop en Sus akan, o sousou me koren.',
    },
    20: {
        1: 'NI ran kaieu en wik Maria men Makdala pwara dong sousou o nin soran, a saikenta ran pasang, ap diaradar, me takai o katapur sanger mon sousou o.',
        2: 'I ap tanga wei, ko dong Simon Petrus o tounpadak teio, me Iesus kotin kupura mauki, indai ong ira: Irail wa sanger Kaun o nan sousou o, a se sasa, wasa re kidi ong ia i.',
        3: 'Petrus ari koieila o tounpadak teio ap ko dong sousou o.',
        4: 'Ira wiaki eu tanga wei, a tounpadak teio me madang mon Petrus lel sousou mas.',
        5: 'A lao itiokidi, ap kilangada likau linen wonon, ap sota pedelong ong lole.',
        6: 'Simon Petrus ap kokodo idauen i, ap pedelong ong nan sousou o, diarada likau linen ko wonon.',
        7: 'O lim en pudo me pira a kadokenmai, me sota iang likau linen ko; a lim pena wasa toror.',
        8: 'A tounpadak teio me tiong dong sousou o, ap pil ko ong lole; i ari diarada o posonla.',
        9: 'Pwe ira kaikenta weweki kisin likau, me a en iasada sang a matala,',
        10: 'Tounpadak ko ap pur onger nan deu’ra.',
        11: 'A Maria u liki sal ong sousou o sangesang. O ni a sangesang a poridi, kilanglong ong nan sousou o,',
        12: 'Kilangada tounlang riamen momod ia, kapwateki likau pwetepwet, amen liman kadokenmai a amen liman aluwilu a kan, wasa kalep en Iesus kotikot iaer,',
        13: 'Ira ari masani ong i: Li, da me koe sangesangki? A indai ong ira: Aki irail wa sanger ai Kaun, a i sasa, wasa re kidi ong ia i.',
        14: 'A lao indada met, ap soupei wei kilanger Iesus kotia u o sasa, me i Iesus.',
        15: 'Iesus kotin masani ong i: Li, da me koe sangesangki? Is me koe kin raparapaki? A kiki ong, me i me saumat o, ap indang i: Maing, ma komui wa sanger i, indai ong ia, wasa komui kidi ong ia i, i ap pan wala sang i.',
        16: 'Iesus ap kotin masani ong i: Maria! I ari soupei ong, potoan ong i: Rapuni! Iet wewe: Saunpadak.',
        17: 'Iesus kotin masani ong i: Der sair ia, pwe I kaikenta pwarala ren Sam ai, a kola ren ri ai kan, kaire kin irail, I kokodala ren Sam ai o Sam omail, ren ai Kot o omail Kot,',
        18: 'Maria men Makdala kodo kaireki tounpadak kan, me a kilangadar Kaun o, o me a kotin masani ong i mepukat.',
        19: 'Lao nin sautik en ran ota, ni ran kaieu en wik, ni wanim ko me ritidier, wasa tounpadak kan pokon pena ia, pweki ar masak Sus oko, Iesus ap kotido u nan pung arail, masani ong irail: Komail popol!',
        20: 'A lao masaniada met, ap kasale ong irail lim a kan o pangepang a. Tounpadak kan ap perenda ni ar kilangada Kaun o.',
        21: 'Iesus ap pil kotin masani ong irail: Komail popol! Duen Sam o kadar ia do, iduen I kadar komail la.',
        22: 'A lao masanier met, ap ngidi ong irail masani: Komail ale Ngen saraui!',
        23: 'Me komail pan lapwada dip ar akan, re lapwadar; o me komail katengedie dip ar akan, pan tengedier.',
        24: 'A Tomas amen ekriamen, me adaneki Didimos, sota iang irail, ni Iesus kotin pwarador.',
        25: 'Tounpadak teio ap indai ong i: Se kilanger Kaun o. A i me indai ong irail: Ma i sota pan kilang lip en mata nan lim a kan, o kilong ong nan lip en mata sondi en pa i, o kilong ong pa ni pangepang a, i sota pan poson.',
        26: 'Murin ran walu sapwilim a tounpadak kan pil pokon pena, o Tomas iang irail. Wanim ko lao ritidier, Iesus ap kotido, u nan pung arail masani: Komail popol!',
        27: 'Ap kotin masani ong Tomas: Kido sondin pa om o kilang pa i kat, o kido pa om, kilong ong nan pangepang ai, o der soposon, a poson ta!',
        28: 'A Tomas sapeng indang i: Ai Kaun o ai Kot!',
        29: 'Iesus kotin masani ong i: Pweki om kilang ia er, koe poson kilar, a meid pai, me kaikenta kilang ap poson.',
        30: 'Kilel toto me so intingidier nan puk wet, me Iesus kotin wiadar nan pung en sapwilim a tounpadak kan.',
        31: 'A mepukat me intingidier, pwe komail en poson, me Iesus me Kristus sapwilim en Kot Ol. O komail en poson ap aneki maur pweki mar a.',
    },
    21: {
        1: 'A MURIN mepukat Iesus pil kasale ong tounpadak kan pein i pon le en Tiperias; a iet duen a kasaledar:',
        2: 'Simon Petrus o Tomas, me adaneki Didimos, o Natanael men Kana nan Kaliläa, o nain Sepedäus ol oko, o pil sapwilim a tounpadak riamen me pokon pena,',
        3: 'Simon Petrus indai ong irail: I pan kola laid. Irail indai ong i: Se pil pan iang uk. Irail ari koieila, kereda pon kisin sop pot. A ni pong o re sota saikidi meakot.',
        4: 'A lao wasa ranier, Iesus ap kotikot ni oror, a sapwilim a tounpadak kan sasa, me i Iesus.',
        5: 'Iesus ap kotin masani ong irail: Seri ko, sota kan omail? Re sapeng i: Sota.',
        6: 'A kotin masani ong irail: Kaduedi uk o pali maun en sop o, a komail pan diarada. Irail ap kaduedi; re ap solar kak apiada pweki mam toto.',
        7: 'Tounpadak o, me Iesus kotin kupura mauki, ap indai ong Petrus: Iei Kaun o. Simon Petrus loa rongadar, me i Kaun o, ap pira ong a sakit en liki pwe a kiliso, ap lusedi ong nan le o.',
        8: 'A tounpadak tei kan seisei kodo nan kisin sop, pwe re so doo sang sap o, ele tipong en pa riepuki, urakido uk o mam oko.',
        9: 'Irail leler sap, rap diaradar kisiniai o mam oko mi poa o prot.',
        10: 'Iesus ap kotin masani ong irail: Wado kisan saik omail!',
        11: 'Simon Petrus ap koda waikelong dong nan sap uk o, me dir en mam kalaimun epuki limek silimen; mam me toto, ari so, uk sota olar.',
        12: 'Iesus kotin masani ong irail: U kodo manga! A sota amen ren tounpadak kan kak idok re a: Is komui? Pwe re asaer, me i Kaun o.',
        13: 'Iesus ap kotido limada prot, nek ong irail o pil mam oko.',
        14: 'A i me kasilepak en Iesus a kotin kasale ong sapwilim a tounpadak kan pein i, murin a iasada sang a matalar.',
        15: 'Irail lao mangaer. Iesus ap kotin masani ong Simon Petrus: Simon, nain Iona, koe kin pok ong ia mon mepukat? A i potoan ong i: Ei Maing, ir me mangi, me i kin pok ong ir. A kotin masani ong i: Apwali nai sippul akan!',
        16: 'A pil masani ong i kariapak: Simon, nain Iona, koe kin pok ong ia? A sapeng i: Ei Maing, ir me kotin mangi, me i kin pok ong ir. A kotin masani ong i: Apwali nai sip akan!',
        17: 'A kotin masani ong i kasilepak: Simon, nain Iona, koe kin pok ong ia? Petrus ap mamauki a peidok pan silepak: Koe pok ong ia? A potoan ong i: Maing, ir me kotin mangi meakaros, re kotin mangi, me i kin pok ong ir. Iesus kotin masani ong i: Apwali nai sip akan!',
        18: 'Melel, melel I indai ong uk, ni om manakap koe pein pirai uk pena, ap alu wei wasa, me koe mauki. A koe lao likailapala, koe nek kida wei pa om akan, a amen pan pirai uk edi o kalualang wasa, me koe kang kola ia.',
        19: 'I me a kotin kokop kidar, duen a pan kapingaki Kot a matala. A lao kotin masanier met, ap masani ong i: Idauen ia!',
        20: 'Petrus ap soupewei, kilang tounpadak o idauen ira, me Iesus kotin kupura mauki o me pil mi pan kupur a ni kamadip o kalelapok: Maing, is i, me pan pang komui la?',
        21: 'Petrus lao kilanger i, ap indai ong Iesus: Maing, menda men et?',
        22: 'Iesus kotin masani ong i: Ma I mauki, a en mimieta I lao puredo, menda re om? Koe en idauen ia!',
        23: 'Kasoi pot et ap loloki sili nan pung en saulang kan, me dene tounpadak o sota pan mela. A Iesus sota kotin masanier, me a sota pan mela, a: Ma I mauki, a en mimieta I lao puredo, menda re om?',
        24: 'Iet tounpadak, me kadele mepukat o intingiedier mepukat; a se asa, me a kadede me melel.',
        25: 'A song toto, me Iesus kotin wiadar a ma irail karos pan intingidi, i lamelame, me sappa sota itar ong koledi puk kan, me pan intingidi.',
    },
}
